insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('d8000000-0000-0000-0000-000000000001', 'mrcp2', '32511ae4-eff2-4f6c-b6ac-ca8673db9378',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('d8000000-0000-0000-0000-000000000001', 'A', 'Stop corticosteroids and await temporal artery biopsy results before starting any treatment, to avoid masking histological changes', false, 'Ruled out because withholding treatment risks irreversible bilateral blindness; biopsy changes persist for a reasonable period after starting steroids, so treatment should never be delayed or stopped pending biopsy in suspected GCA with visual loss.', 1),
('d8000000-0000-0000-0000-000000000001', 'B', 'Continue IV methylprednisolone for 3 days, then transition to oral prednisolone 60 mg daily, and arrange temporal artery biopsy within 7-14 days without delaying treatment', true, 'Correct. This presentation (sudden monocular visual loss, pale swollen disc, jaw claudication, markedly raised inflammatory markers) is classic for arteritic anterior ischaemic optic neuropathy due to giant cell arteritis, an ophthalmic emergency because the fellow eye is at high risk of involvement within days if untreated. High-dose IV corticosteroids should be started immediately (already done here) and continued for pulse therapy before transitioning to a high-dose oral regimen; temporal artery biopsy should be arranged but must never delay treatment, and remains informative for up to 2 weeks after starting steroids due to the characteristic granulomatous changes persisting.', 2),
('d8000000-0000-0000-0000-000000000001', 'C', 'Switch immediately to oral prednisolone 40 mg daily as first-line, reserving IV pulse steroids only for biopsy-proven cases', false, 'Ruled out because visual loss in GCA is an indication for urgent high-dose IV pulse methylprednisolone (not lower-dose oral therapy first), given the risk of rapid bilateral involvement; treatment should not be de-escalated or delayed pending biopsy confirmation.', 3),
('d8000000-0000-0000-0000-000000000001', 'D', 'Arrange urgent temporal artery biopsy and start low-molecular-weight heparin for presumed retinal artery occlusion, deferring steroids', false, 'Ruled out because this is optic nerve ischaemia due to vasculitis, not a simple thromboembolic retinal artery occlusion; anticoagulation has no proven role, and steroids are the priority urgent intervention, not to be deferred.', 4),
('d8000000-0000-0000-0000-000000000001', 'E', 'Perform intravitreal anti-VEGF injection to the right eye as the priority intervention', false, 'Ruled out because anti-VEGF therapy has no role in arteritic AION; the priority is systemic corticosteroids to prevent further ischaemic damage and protect the fellow eye.', 5),
('d8000000-0000-0000-0000-000000000002', 'A', 'Urgent referral for consideration of ocular massage, and same-day assessment for any thrombolysis pathway per local stroke protocol, alongside urgent stroke/cardiovascular risk factor workup', true, 'Correct. Central retinal artery occlusion (CRAO) presenting within a narrow time window from onset (generally under 4.5 hours, ideally under 4 hours) should prompt urgent discussion with a stroke/ophthalmology team regarding thrombolysis, as CRAO is now recognised as a retinal stroke equivalent; simple measures such as ocular massage may be attempted while arranging this, and urgent cardiovascular and embolic source workup (carotid imaging, echocardiogram, ECG) should follow given the significant risk of concurrent cerebral stroke and the need to identify treatable underlying causes such as carotid disease or cardioembolism from his atrial fibrillation.', 1),
('d8000000-0000-0000-0000-000000000002', 'B', 'Reassure the patient that visual loss from CRAO is permanent and no acute intervention is indicated; arrange routine ophthalmology follow-up', false, 'Ruled out because within the acute time window, CRAO should be treated as a time-critical retinal stroke with consideration of urgent reperfusion strategies and stroke-pathway assessment, not managed with reassurance and routine follow-up alone.', 2),
('d8000000-0000-0000-0000-000000000002', 'C', 'Start intravitreal anti-VEGF therapy as the priority intervention to reverse the occlusion', false, 'Ruled out because anti-VEGF therapy has no role in acute CRAO management; it does not restore retinal perfusion and is used later for complications such as neovascularisation, not as an emergency reperfusion strategy.', 3),
('d8000000-0000-0000-0000-000000000002', 'D', 'Increase the apixaban dose empirically to improve retinal perfusion', false, 'Ruled out because empirically increasing anticoagulant dose is not an evidence-based intervention for CRAO and risks bleeding complications; the priority is urgent reperfusion assessment and addressing the underlying embolic source through standard secondary prevention pathways.', 4),
('d8000000-0000-0000-0000-000000000002', 'E', 'Arrange elective carotid endarterectomy within the next month before any other intervention', false, 'Ruled out because this delays the time-critical acute assessment; carotid imaging and intervention are part of the subsequent secondary-prevention workup, not the immediate priority, which is urgent stroke-pathway assessment for possible reperfusion.', 5),
('d8000000-0000-0000-0000-000000000003', 'A', 'Reassure the patient that BRVO resolves spontaneously and no treatment or investigation is required', false, 'Ruled out because while some BRVO cases stabilise, macular oedema causing reduced acuity warrants active treatment with anti-VEGF or other therapies to preserve vision, and systemic risk factors should be assessed.', 1),
('d8000000-0000-0000-0000-000000000003', 'B', 'Proceed directly to panretinal photocoagulation as first-line treatment', false, 'Ruled out because panretinal photocoagulation is used for retinal neovascularisation/ischaemic complications, not as first-line treatment for macular oedema without evidence of neovascularisation; anti-VEGF is first-line for macular oedema.', 2),
('d8000000-0000-0000-0000-000000000003', 'C', 'Start high-dose oral corticosteroids as the primary treatment for macular oedema', false, 'Ruled out because oral corticosteroids are not standard first-line treatment for BRVO-related macular oedema; intravitreal anti-VEGF (or, in some cases, intravitreal steroid implants) are used, and systemic steroids carry unfavourable risk-benefit in this context.', 3),
('d8000000-0000-0000-0000-000000000003', 'D', 'Refer urgently for carotid endarterectomy prior to any ophthalmic intervention', false, 'Ruled out because BRVO is a retinal venous occlusion related to local vascular/rheological factors at arteriovenous crossing points and systemic vascular risk factors, not typically an embolic carotid disease requiring endarterectomy; the priority is ocular treatment and risk factor control.', 4),
('d8000000-0000-0000-0000-000000000003', 'E', 'Arrange intravitreal anti-VEGF therapy for macular oedema, alongside investigation and optimisation of cardiovascular risk factors (blood pressure, lipids, glucose)', true, 'Correct. This is a branch retinal vein occlusion (BRVO) with associated macular oedema causing reduced visual acuity; intravitreal anti-VEGF agents are first-line treatment for BRVO-associated macular oedema and have been shown to improve visual outcomes. Alongside ocular treatment, systemic risk factor assessment and optimisation (hypertension, dyslipidaemia, diabetes screening) are essential, as BRVO shares risk factors with other vascular disease.', 5),
('d8000000-0000-0000-0000-000000000004', 'A', 'Rhegmatogenous retinal detachment; arrange emergency scleral buckling within hours regardless of B-scan findings', false, $x$Ruled out because the B-scan here shows vitreous echoes without evidence of retinal detachment; while retinal detachment must always be excluded in this context, this case's findings support vitreous haemorrhage as the primary diagnosis, and the correct next step is monitoring with serial imaging rather than presuming a detachment requiring emergency buckling.$x$, 1),
('d8000000-0000-0000-0000-000000000004', 'B', 'Endophthalmitis; start intravitreal antibiotics empirically', false, 'Ruled out because there are no features of infection (pain, hypopyon, recent intraocular surgery/trauma) — this presentation is a vascular/proliferative retinopathy complication, not endophthalmitis, so intravitreal antibiotics are not indicated.', 2),
('d8000000-0000-0000-0000-000000000004', 'C', 'Vitreous haemorrhage secondary to proliferative diabetic retinopathy; manage conservatively initially with follow-up B-scan ultrasound to exclude retinal detachment, with vitrectomy considered if it fails to clear', true, 'Correct. Sudden visual loss with floaters/black spots and vitreous echoes on B-scan (in the absence of visible fundal detail) in a patient with severe background diabetic retinopathy is classic for vitreous haemorrhage from proliferative diabetic retinopathy (neovascularisation bleeding into the vitreous). Initial management is typically conservative (positioning, monitoring) with serial B-scan ultrasonography to exclude an underlying retinal detachment (which would change management urgency); if haemorrhage fails to clear over weeks or a detachment is found, pars plana vitrectomy is indicated, along with panretinal photocoagulation for the underlying proliferative disease once view is adequate.', 3),
('d8000000-0000-0000-0000-000000000004', 'D', 'Acute angle-closure glaucoma; start topical and systemic pressure-lowering treatment and refer for laser iridotomy', false, 'Ruled out because this presentation lacks the pain, red eye, fixed mid-dilated pupil and raised intraocular pressure characteristic of angle closure; the clinical picture and B-scan findings instead indicate vitreous haemorrhage.', 4),
('d8000000-0000-0000-0000-000000000004', 'E', 'Optic neuritis; start high-dose intravenous corticosteroids', false, 'Ruled out because optic neuritis typically causes painful visual loss with a relative afferent pupillary defect and normal fundal media, not vitreous echoes on B-scan; this presentation is explained by vitreous haemorrhage in the context of proliferative diabetic retinopathy.', 5),
('d8000000-0000-0000-0000-000000000005', 'A', 'Increase acetazolamide further, as visual field loss indicates inadequate dosing rather than treatment failure', false, 'Ruled out because dosing is already described as maximally tolerated; continuing to escalate medical therapy while visual fields progressively deteriorate risks permanent visual loss, and surgical intervention should be pursued at this stage.', 1),
('d8000000-0000-0000-0000-000000000005', 'B', 'Add high-dose oral corticosteroids as the next step, given their proven long-term benefit in idiopathic intracranial hypertension', false, 'Ruled out because corticosteroids are not standard long-term therapy for IIH (risk of rebound with withdrawal and weight gain worsening the underlying problem); they are not the appropriate next step for progressive field loss on maximal acetazolamide.', 2),
('d8000000-0000-0000-0000-000000000005', 'C', 'Repeat lumbar puncture for therapeutic drainage as a long-term management strategy in place of surgery', false, 'Ruled out because repeated therapeutic lumbar punctures are not a sustainable long-term strategy for progressive visual loss in IIH; definitive surgical intervention (nerve sheath fenestration or CSF shunting) is indicated when medical therapy fails and vision is threatened.', 3),
('d8000000-0000-0000-0000-000000000005', 'D', 'Refer urgently for surgical intervention (optic nerve sheath fenestration or CSF diversion procedure such as ventriculoperitoneal/lumboperitoneal shunting) given progressive visual field loss despite maximal medical therapy', true, 'Correct. Progressive visual field deterioration despite maximally tolerated medical therapy (acetazolamide plus weight management) in idiopathic intracranial hypertension is an indication for urgent surgical intervention to prevent irreversible visual loss, as papilloedema-related field loss can become permanent. Options include optic nerve sheath fenestration (more direct protection of the optic nerve) or CSF diversion procedures (ventriculoperitoneal or lumboperitoneal shunt), with the choice guided by local expertise and clinical picture; the key teaching point is that ongoing field deterioration on maximal medical therapy is a surgical trigger, not an indication to simply continue or escalate medical treatment alone.', 4),
('d8000000-0000-0000-0000-000000000005', 'E', 'Discharge with reassurance that transient visual obscurations do not indicate structural threat to vision', false, 'Ruled out because new, persistent inferior nasal field loss on formal perimetry (not just transient obscurations) indicates evolving optic nerve damage from papilloedema, which requires urgent escalation, not reassurance and discharge.', 5),
('d8000000-0000-0000-0000-000000000006', 'A', 'Start long-term oral prednisolone alone, as this is more effective than intravenous steroids for optic neuritis', false, 'Ruled out because oral corticosteroids alone (particularly low/moderate dose without preceding IV pulse) have historically been associated with an increased rate of recurrent optic neuritis in trial data, and are not the preferred approach; IV methylprednisolone is used when treatment is offered.', 1),
('d8000000-0000-0000-0000-000000000006', 'B', 'Reassure that no treatment is required or beneficial in optic neuritis and no further specialist referral is needed', false, 'Ruled out because although visual recovery often occurs without treatment, IV steroids can hasten recovery, and critically, this patient has radiological and clinical evidence of disseminated disease requiring neurology referral for disease-modifying therapy consideration, which should not be omitted.', 2),
('d8000000-0000-0000-0000-000000000006', 'C', 'Start disease-modifying therapy for multiple sclerosis immediately in the eye clinic without neurology input', false, 'Ruled out because initiation and choice of disease-modifying therapy for multiple sclerosis should be managed by neurology following full assessment, not initiated unilaterally in an ophthalmology setting.', 3),
('d8000000-0000-0000-0000-000000000006', 'D', 'Offer high-dose intravenous methylprednisolone to hasten visual recovery, while counselling that it does not alter the long-term visual outcome, alongside referral to neurology for disease-modifying therapy given radiological evidence of dissemination', true, 'Correct. This is optic neuritis in the context of clinically and radiologically confirmed multiple sclerosis. IV methylprednisolone accelerates visual recovery in acute optic neuritis but does not change the final visual outcome at 6-12 months compared with no treatment; it is nonetheless commonly offered to speed recovery, particularly with significant visual impairment. Given MRI evidence of dissemination in space, and a prior clinically compatible episode, this fulfils criteria for a diagnosis of multiple sclerosis, so referral to neurology for consideration of disease-modifying therapy is appropriate to reduce future relapse risk and disability accumulation, which is now a key part of managing optic neuritis in this context.', 4),
('d8000000-0000-0000-0000-000000000006', 'E', 'Proceed to optic nerve sheath decompression surgery as the primary intervention', false, 'Ruled out because optic nerve sheath surgery has no role in inflammatory demyelinating optic neuritis; management is medical (corticosteroids for recovery, disease-modifying therapy for the underlying MS), not surgical.', 5),
('d8000000-0000-0000-0000-000000000007', 'A', 'Start high-dose oral corticosteroids urgently as first-line treatment to reverse the optic neuropathy', false, 'Ruled out because corticosteroids are the treatment for arteritic AION due to GCA, not for non-arteritic AION, where there is no clear evidence of benefit from steroids and the underlying pathophysiology (small-vessel ischaemia in a crowded disc) differs from vasculitic disease.', 1),
('d8000000-0000-0000-0000-000000000007', 'B', 'Arrange emergency temporal artery biopsy given the risk of giant cell arteritis', false, 'Ruled out because the clinical picture (younger age relative to typical GCA, hyperaemic rather than pale disc, absence of systemic GCA symptoms, normal inflammatory markers) is not consistent with arteritic AION, making urgent biopsy unnecessary; the diagnosis here is non-arteritic AION.', 2),
('d8000000-0000-0000-0000-000000000007', 'C', 'Manage conservatively (no proven disease-modifying treatment for the optic neuropathy itself), optimise vascular risk factors, and refer for assessment and treatment of obstructive sleep apnoea', true, $x$Correct. This presentation (painless visual field loss on waking, hyperaemic swollen disc rather than pale, normal inflammatory markers, no GCA symptoms) is typical of non-arteritic anterior ischaemic optic neuropathy (NAION), which occurs in patients with vascular risk factors and a 'disc at risk' (small cup-to-disc ratio). There is no proven treatment that reverses the optic neuropathy itself; management focuses on optimising modifiable vascular risk factors (glycaemic control, blood pressure) and treating obstructive sleep apnoea, which is a recognised independent risk factor for NAION and for fellow-eye involvement.$x$, 3),
('d8000000-0000-0000-0000-000000000007', 'D', 'Perform intravitreal anti-VEGF injection as first-line therapy for the optic neuropathy', false, 'Ruled out because anti-VEGF therapy has no established role in NAION; it targets retinal/choroidal neovascularisation processes, not ischaemic optic nerve injury.', 4),
('d8000000-0000-0000-0000-000000000007', 'E', 'Advise that no further action or investigation is required, as NAION carries no risk to the fellow eye', false, 'Ruled out because NAION carries a meaningful risk (historically cited around 15-20%) of fellow-eye involvement over subsequent years, so ongoing risk factor optimisation and monitoring are important, not simple reassurance.', 5),
('d8000000-0000-0000-0000-000000000008', 'A', 'Continue hydroxychloroquine at the same dose since her visual acuity is only mildly affected, and simply monitor with annual OCT', false, 'Ruled out because once retinopathy is identified, hydroxychloroquine should be stopped rather than continued at the same dose, as toxicity can progress even after cessation, and continuing exposure at a dose above the recommended maximum risks further irreversible damage.', 1),
('d8000000-0000-0000-0000-000000000008', 'B', 'Stop hydroxychloroquine and discuss alternative disease-modifying therapy for her lupus with rheumatology, given clinical and OCT evidence of hydroxychloroquine retinal toxicity', true, $x$Correct. The bull's-eye maculopathy, paracentral scotomas, and parafoveal ellipsoid zone loss ('flying saucer sign') on OCT are classic findings of hydroxychloroquine retinopathy, and her cumulative dose (6.8 mg/kg/day actual body weight, above the recommended maximum of 5 mg/kg/day) and long duration of use place her at significantly increased risk. Once retinal toxicity is identified, hydroxychloroquine should be discontinued, as continuing treatment risks progression of maculopathy even after stopping ('lipofuscin' continued toxicity), and alternative disease-modifying therapy should be discussed with rheumatology to manage her lupus.$x$, 2),
('d8000000-0000-0000-0000-000000000008', 'C', 'Reduce the hydroxychloroquine dose to 200 mg daily and continue indefinitely with no further monitoring required', false, 'Ruled out because once definite retinal toxicity is present, the standard approach is to stop the drug rather than simply reduce the dose and abandon monitoring; ongoing surveillance would still be required if any hydroxychloroquine were continued, but stopping and switching agents is preferred once toxicity is confirmed.', 3),
('d8000000-0000-0000-0000-000000000008', 'D', 'Attribute the maculopathy to lupus-related retinal vasculitis and increase mycophenolate dose', false, $x$Ruled out because the described findings (bull's-eye maculopathy, parafoveal ellipsoid zone loss) are the specific signature of hydroxychloroquine toxicity, not lupus retinal vasculopathy (which typically shows cotton wool spots, vascular occlusions and haemorrhages); increasing immunosuppression would not address the underlying drug toxicity.$x$, 4),
('d8000000-0000-0000-0000-000000000008', 'E', 'Arrange intravitreal anti-VEGF therapy as first-line treatment for the maculopathy', false, 'Ruled out because there is no role for anti-VEGF therapy in hydroxychloroquine retinopathy; the management is drug cessation, not intravitreal treatment targeting neovascularisation.', 5),
('d8000000-0000-0000-0000-000000000009', 'A', 'Send corneal scrapings for specific Acanthamoeba culture/PCR and consider empirical topical biguanide (e.g. polyhexamethylene biguanide) therapy given the clinical features and lack of response to antibacterial treatment', true, 'Correct. Radial perineural infiltrates and a ring-shaped stromal infiltrate in a contact lens wearer with poor response to intensive topical antibacterial therapy are highly suggestive of Acanthamoeba keratitis, a diagnosis that is often delayed because it mimics bacterial or herpetic keratitis. Specific investigations (Acanthamoeba culture on non-nutrient agar with E. coli overlay, PCR, or in vivo confocal microscopy) should be pursued, and empirical treatment with topical biguanide agents (with or without a diamidine) should be considered promptly given the risk of progression and poor outcomes with delayed treatment.', 1),
('d8000000-0000-0000-0000-000000000009', 'B', 'Continue the same topical fluoroquinolone at a higher frequency, as most bacterial keratitis simply requires longer treatment before response', false, 'Ruled out because the clinical picture (contact lens wear, ring infiltrate, radial perineural infiltrates, treatment failure) strongly suggests Acanthamoeba rather than bacterial keratitis, which would not be expected to respond to continued antibacterial therapy alone; a change in diagnostic and treatment approach is needed.', 2),
('d8000000-0000-0000-0000-000000000009', 'C', 'Start topical aciclovir for presumed herpes simplex keratitis without further investigation', false, 'Ruled out because although herpetic keratitis is a differential for atypical keratitis, the described ring infiltrate and radial perineural infiltrates in a contact lens wearer are more specific for Acanthamoeba, and empirical antiviral treatment alone would not address this without appropriate diagnostic testing directed at Acanthamoeba.', 3),
('d8000000-0000-0000-0000-000000000009', 'D', 'Perform emergency penetrating keratoplasty as first-line management at this stage', false, 'Ruled out because corneal transplantation is reserved for cases with impending or actual perforation, or medically unresponsive advanced disease, not as a first response to antibacterial treatment failure; medical therapy directed at the likely organism should be tried first.', 4),
('d8000000-0000-0000-0000-000000000009', 'E', 'Discontinue all treatment and observe, as most microbial keratitis resolves spontaneously in contact lens wearers', false, 'Ruled out because untreated Acanthamoeba (or bacterial) keratitis can progress to corneal perforation and severe visual loss; active treatment directed at the correct organism is required, not observation.', 5),
('d8000000-0000-0000-0000-000000000010', 'A', 'Continue the current 8-weekly interval unchanged, as some fluctuation in OCT findings is expected and does not require intervention', false, 'Ruled out because new subretinal fluid with symptomatic distortion and increased central thickness represents active disease reactivation, not an incidental fluctuation, and requires prompt treatment rather than continuing an interval that has proven too long for this patient.', 1),
('d8000000-0000-0000-0000-000000000010', 'B', 'Switch immediately to photodynamic therapy as first-line treatment, abandoning anti-VEGF therapy', false, 'Ruled out because anti-VEGF therapy remains first-line for neovascular AMD reactivation; photodynamic therapy is not the standard first response to breakthrough disease on a treat-and-extend regimen and would not be initiated in place of continued/adjusted anti-VEGF treatment as a first step.', 2),
('d8000000-0000-0000-0000-000000000010', 'C', 'Arrange for laser photocoagulation to the subfoveal lesion as the priority intervention', false, 'Ruled out because laser photocoagulation directly to subfoveal neovascular lesions would cause central scotoma and is not appropriate management for neovascular AMD reactivation; anti-VEGF therapy is the appropriate treatment.', 3),
('d8000000-0000-0000-0000-000000000010', 'D', 'Discontinue anti-VEGF therapy altogether since disease reactivation indicates treatment futility', false, 'Ruled out because reactivation on a treat-and-extend interval reflects the interval being too long for this individual, not treatment futility; the correct response is to treat promptly and adjust the interval or switch agent, not to abandon anti-VEGF therapy.', 4),
('d8000000-0000-0000-0000-000000000010', 'E', 'Bring forward his intravitreal anti-VEGF injection and consider reverting to a shorter treatment interval or switching agent if reactivation recurs on the current regimen', true, 'Correct. New subretinal fluid and metamorphopsia with increasing central subfield thickness ahead of a scheduled injection indicate disease reactivation on his current treat-and-extend interval, meaning the interval has been extended beyond his individual tolerance. The appropriate response is to bring forward treatment promptly (do not wait for the scheduled visit) and adjust the regimen — typically shortening the interval again, and if recurrent reactivation continues despite interval adjustment, considering a switch to an alternative anti-VEGF agent (e.g. a different mechanism or longer intrinsic durability) is a recognised strategy in refractory or breakthrough neovascular AMD.', 5),
('d8000000-0000-0000-0000-000000000011', 'A', 'Manage conservatively with observation for 2 weeks to allow swelling to settle before considering surgery', false, 'Ruled out because true muscle entrapment in a trapdoor fracture requires urgent surgical release; delaying repair by weeks risks permanent ischaemic damage to the inferior rectus muscle and permanent restrictive diplopia, unlike simple orbital floor fractures without entrapment which may be observed.', 1),
('d8000000-0000-0000-0000-000000000011', 'B', 'Arrange urgent (within 24-48 hours) surgical repair given evidence of inferior rectus entrapment with a trapdoor fracture pattern in a young patient', true, $x$Correct. A trapdoor orbital floor fracture with entrapment of the inferior rectus muscle in a young patient is a surgical emergency (sometimes termed the 'white-eyed blowout fracture' when the globe appears deceptively quiet) because muscle ischaemia can rapidly cause permanent fibrosis and restrictive strabismus, and the oculocardiac reflex (bradycardia, nausea, vomiting from vagal stimulation with eye movement) further supports urgent repair. Unlike many orbital floor fractures, which can be managed conservatively or with delayed repair, trapdoor fractures with true entrapment require urgent surgical release, typically within 24-48 hours, to prevent permanent muscle damage.$x$, 2),
('d8000000-0000-0000-0000-000000000011', 'C', 'Start high-dose oral corticosteroids alone as definitive treatment to reduce muscle swelling and avoid surgery', false, 'Ruled out because corticosteroids may be used adjunctively to reduce oedema but do not address true mechanical entrapment; definitive management of entrapment is urgent surgical release, not medical therapy alone.', 3),
('d8000000-0000-0000-0000-000000000011', 'D', 'Reassure the patient that diplopia will resolve spontaneously without any intervention required', false, 'Ruled out because entrapment causing restricted eye movement with an oculocardiac reflex requires urgent surgical intervention; without treatment, permanent fibrosis and restrictive strabismus are likely, so reassurance without action is inappropriate.', 4),
('d8000000-0000-0000-0000-000000000011', 'E', $x$Arrange elective repair in 3 months' time once diplopia has been formally quantified by orthoptic assessment$x$, false, 'Ruled out because entrapment in a trapdoor fracture in a young patient needs urgent (not delayed elective) repair, given the rapid risk of irreversible ischaemic muscle damage if release is postponed.', 5),
('d8000000-0000-0000-0000-000000000012', 'A', 'Perform trabeculectomy as the sole first-line intervention without addressing retinal ischaemia', false, 'Ruled out because filtering surgery alone in the presence of active neovascularisation has a high failure rate and risk of complications (e.g. hyphaema) due to bleeding from new vessels; panretinal photocoagulation to treat the underlying ischaemic drive is required first or alongside any surgical intervention.', 1),
('d8000000-0000-0000-0000-000000000012', 'B', 'Manage with topical corticosteroids alone, as this represents anterior uveitis rather than neovascular disease', false, 'Ruled out because the described new vessels at the iris and angle with markedly raised intraocular pressure in a patient with known ischaemic CRVO is neovascular glaucoma, not simple anterior uveitis; topical steroids alone would not address the underlying neovascular process or pressure crisis.', 2),
('d8000000-0000-0000-0000-000000000012', 'C', 'Reassure that this is an expected late finding after CRVO requiring no specific treatment', false, 'Ruled out because neovascular glaucoma is a sight- and often globe-threatening emergency requiring urgent treatment (panretinal photocoagulation, anti-VEGF, IOP control), not observation.', 3),
('d8000000-0000-0000-0000-000000000012', 'D', 'Start oral acetazolamide alone and review in 6 weeks', false, 'Ruled out because while pressure-lowering treatment (including acetazolamide) forms part of management, addressing the underlying retinal ischaemia with urgent panretinal photocoagulation (± anti-VEGF) is essential and should not be delayed for 6 weeks given the risk of rapidly progressive, painful, blind eye.', 4),
('d8000000-0000-0000-0000-000000000012', 'E', 'Arrange urgent panretinal photocoagulation alongside intravitreal anti-VEGF therapy and intraocular pressure-lowering treatment for neovascular glaucoma', true, $x$Correct. This is ischaemic central retinal vein occlusion complicated by neovascular glaucoma (rubeosis iridis with new vessels at the angle and markedly raised intraocular pressure), typically occurring around 3 months after ischaemic CRVO ('90-day glaucoma'). Management requires urgent panretinal photocoagulation to suppress the ischaemia-driven VEGF drive for neovascularisation, often combined with intravitreal anti-VEGF therapy for more rapid regression of new vessels, alongside topical/systemic intraocular pressure-lowering treatment; delay risks intractable glaucoma and a blind, painful eye.$x$, 5),
('d8000000-0000-0000-0000-000000000013', 'A', 'Diagnose acute angle closure and start pressure-lowering treatment', false, 'Ruled out because there is no evidence of angle closure (pain, red eye, raised intraocular pressure, fixed pupil); this presentation is explained by known diabetic retinopathy changes associated with glycaemic correction.', 1),
('d8000000-0000-0000-0000-000000000013', 'B', 'Deliberately allow blood glucose to remain elevated to avoid further retinopathy progression', false, 'Ruled out because deliberately maintaining hyperglycaemia is harmful in the longer term and not the recommended response to early worsening; the correct approach is continued appropriate glycaemic control with closer retinal monitoring, since early worsening is usually transient.', 2),
('d8000000-0000-0000-0000-000000000013', 'C', 'Early worsening of diabetic retinopathy associated with rapid glycaemic correction; continue careful glycaemic control with close ophthalmological monitoring rather than reversing treatment', true, 'Correct. Rapid correction of chronic severe hyperglycaemia is a well-recognised cause of transient early worsening of diabetic retinopathy, thought to relate to retinal blood flow changes and a temporary imbalance in growth factor signalling as glycaemia normalises. This is usually self-limiting, and the correct approach is to continue appropriate glycaemic control (not deliberately under-treat glucose) while increasing the frequency of ophthalmological monitoring, since a minority of patients can progress further and would need specific retinopathy treatment if that occurs.', 3),
('d8000000-0000-0000-0000-000000000013', 'D', 'Arrange immediate panretinal photocoagulation regardless of the absence of proliferative changes', false, 'Ruled out because panretinal photocoagulation is indicated for proliferative diabetic retinopathy or high-risk features, not for early worsening without proliferative changes; the correct approach here is monitoring, with treatment reserved if disease progresses to a treatment-requiring stage.', 4),
('d8000000-0000-0000-0000-000000000013', 'E', 'Attribute the findings to hypertensive retinopathy secondary to her chronic kidney disease and start antihypertensive therapy alone', false, 'Ruled out because the clinical context (known diabetic retinopathy, recent rapid glycaemic correction, cotton wool spots without other hypertensive features described) points to early worsening of diabetic retinopathy rather than hypertensive retinopathy as the primary explanation, though blood pressure should of course also be optimised as part of overall care.', 5),
('d8000000-0000-0000-0000-000000000014', 'A', 'Focal/grid macular laser photocoagulation alone as first-line treatment, given its lower treatment burden', false, 'Ruled out because although laser was historically first-line, anti-VEGF therapy has superior visual outcomes for centre-involving diabetic macular oedema with vision loss and is now the preferred first-line treatment; laser remains an option for non-centre-involving oedema or as adjunctive/second-line therapy.', 1),
('d8000000-0000-0000-0000-000000000014', 'B', 'Intravitreal corticosteroid implant (e.g. dexamethasone) as first-line treatment given his desire to minimise visit frequency', false, 'Ruled out because intravitreal corticosteroids are generally reserved as second-line therapy (e.g. in pseudophakic patients or those with an inadequate response/intolerance to anti-VEGF), given the risks of cataract progression and intraocular pressure elevation; anti-VEGF remains first-line in phakic patients without prior treatment.', 2),
('d8000000-0000-0000-0000-000000000014', 'C', 'Observation alone with repeat OCT in 6 months, given his lack of cardiovascular disease', false, 'Ruled out because centre-involving diabetic macular oedema with reduced visual acuity (6/18) and significant central thickening requires active treatment; observation alone risks progressive, potentially irreversible visual loss.', 3),
('d8000000-0000-0000-0000-000000000014', 'D', 'Intravitreal anti-VEGF therapy (e.g. aflibercept or ranibizumab) as first-line treatment, with an initial loading phase of monthly injections', true, 'Correct. Intravitreal anti-VEGF therapy is first-line treatment for centre-involving diabetic macular oedema with reduced visual acuity, supported by robust trial evidence (e.g. RESTORE, RISE/RIDE, VIVID/VISTA) showing superior visual outcomes compared with laser alone. An initial loading phase (typically monthly injections for around 3-6 doses) is required to achieve disease control before extending treatment intervals; this involves a frequent early visit burden, which should be discussed with the patient, but represents the standard of care given his reduced acuity and significant central thickening.', 4),
('d8000000-0000-0000-0000-000000000014', 'E', 'Urgent vitrectomy as first-line treatment for diabetic macular oedema', false, 'Ruled out because vitrectomy is not first-line treatment for diabetic macular oedema; it is reserved for specific indications such as tractional macular oedema with a taut posterior hyaloid or vitreomacular traction, not routine centre-involving oedema without traction.', 5),
('d8000000-0000-0000-0000-000000000015', 'A', 'Switch to an alternative anti-VEGF agent (e.g. from aflibercept to a different agent, or vice versa) or consider intravitreal corticosteroid therapy given inadequate response after an adequate loading course', true, $x$Correct. An inadequate anatomical and functional response after a full loading course (around 6 monthly injections) of one anti-VEGF agent is a recognised indication to switch to an alternative anti-VEGF agent, since individual patient response can vary between agents, or to consider intravitreal corticosteroid therapy (e.g. dexamethasone implant), which works through a different anti-inflammatory mechanism and can be effective in anti-VEGF partial/non-responders. This reflects the 'treat, extend, and switch if needed' philosophy central to modern DMO management.$x$, 1),
('d8000000-0000-0000-0000-000000000015', 'B', 'Continue the same anti-VEGF agent at the same monthly frequency indefinitely, as response can take over a year to manifest', false, 'Ruled out because after an adequate loading course with minimal anatomical or functional improvement, continuing unchanged therapy without considering a change in agent or modality is not appropriate; switching agent or modality is the recommended next step for inadequate responders.', 2),
('d8000000-0000-0000-0000-000000000015', 'C', 'Stop all treatment, as lack of response indicates macular oedema is not treatable in this patient', false, 'Ruled out because inadequate response to one specific agent does not mean the condition is untreatable; switching to an alternative anti-VEGF agent or corticosteroid therapy often achieves better control, so stopping all treatment is not appropriate.', 3),
('d8000000-0000-0000-0000-000000000015', 'D', 'Proceed directly to vitrectomy as the next step given anti-VEGF non-response', false, 'Ruled out because vitrectomy is not a standard next step for anti-VEGF partial-responder diabetic macular oedema without vitreomacular traction; switching pharmacological agent/modality is the appropriate next step.', 4),
('d8000000-0000-0000-0000-000000000015', 'E', 'Add focal laser photocoagulation as monotherapy in place of further intravitreal therapy', false, 'Ruled out because focal laser alone is not superior to continued/adjusted intravitreal pharmacotherapy in centre-involving DMO with an inadequate anti-VEGF response; switching agent or considering corticosteroid therapy is the preferred next step, with laser sometimes used adjunctively rather than replacing intravitreal treatment entirely.', 5),
('d8000000-0000-0000-0000-000000000016', 'A', 'Continue routine annual diabetic eye screening in the community, as no proliferative changes or macular oedema are present', false, 'Ruled out because severe non-proliferative diabetic retinopathy carries a substantial short-term risk of progression to proliferative disease and needs closer surveillance via the hospital eye service, not simply continued routine annual community screening.', 1),
('d8000000-0000-0000-0000-000000000016', 'B', 'Refer to hospital eye service for close monitoring given severe non-proliferative diabetic retinopathy, with consideration of early panretinal photocoagulation discussed on an individual basis, rather than routine annual screening', true, $x$Correct. This describes severe non-proliferative diabetic retinopathy (meeting the '4-2-1 rule': haemorrhages in all 4 quadrants, venous beading in ≥2 quadrants, or IRMA in ≥1 quadrant — here multiple features are present), which carries a high risk (approximately 50%) of progression to proliferative disease within a year. Such patients should be referred to hospital eye services for closer monitoring (rather than routine community screening intervals), and in selected high-risk patients (e.g. poor follow-up compliance, contralateral eye already proliferative, or other risk factors), earlier panretinal photocoagulation may be considered even before frank proliferative changes develop.$x$, 2),
('d8000000-0000-0000-0000-000000000016', 'C', 'Perform panretinal photocoagulation immediately in all cases regardless of individual risk factors, as this is mandatory at this stage', false, 'Ruled out because panretinal photocoagulation is not universally mandatory at the severe non-proliferative stage; it is considered on an individualised basis for high-risk patients, while most are managed with close monitoring until proliferative changes or high-risk features develop.', 3),
('d8000000-0000-0000-0000-000000000016', 'D', 'Start intravitreal anti-VEGF therapy now to prevent progression to proliferative disease', false, 'Ruled out because anti-VEGF therapy is not standard treatment for severe non-proliferative disease without macular oedema or proliferative changes; the priority is closer monitoring (and selectively, early laser) rather than intravitreal pharmacotherapy at this stage.', 4),
('d8000000-0000-0000-0000-000000000016', 'E', 'Discharge back to primary care with no specific follow-up given normal visual acuity', false, 'Ruled out because normal visual acuity does not reflect the significant structural risk of progression in severe NPDR; closer hospital eye service follow-up is required rather than discharge.', 5),
('d8000000-0000-0000-0000-000000000017', 'A', 'Start intravitreal anti-VEGF therapy for the new centre-involving macular oedema, continuing panretinal photocoagulation follow-up as needed for the proliferative disease', true, 'Correct. Worsening or new-onset macular oedema following panretinal photocoagulation is a recognised complication, thought to relate to a transient inflammatory/VEGF response to laser treatment. When centre-involving oedema develops or worsens after PRP, intravitreal anti-VEGF therapy is appropriate to treat the oedema while continuing to manage the underlying proliferative disease (completing PRP as required); anti-VEGF therapy has also been shown to be effective as monotherapy for proliferative disease in some contexts, but here with combined vitreous haemorrhage history and completed PRP, the priority addition is treating the new macular oedema.', 1),
('d8000000-0000-0000-0000-000000000017', 'B', 'Stop all treatment and observe, as post-laser macular oedema always resolves spontaneously within days', false, 'Ruled out because although some post-laser macular oedema can be transient, centre-involving oedema causing symptomatic visual decline should be actively treated with anti-VEGF therapy rather than simply observed, particularly given the risk of prolonged visual impairment.', 2),
('d8000000-0000-0000-0000-000000000017', 'C', 'Repeat panretinal photocoagulation immediately at a higher laser energy setting to address the oedema', false, 'Ruled out because increasing laser burden does not treat macular oedema and may worsen it further; the oedema itself should be treated with anti-VEGF therapy, not by intensifying PRP.', 3),
('d8000000-0000-0000-0000-000000000017', 'D', 'Arrange emergency vitrectomy for the macular oedema', false, 'Ruled out because vitrectomy is not indicated for macular oedema without tractional features; anti-VEGF therapy is the appropriate first-line treatment for centre-involving macular oedema in this context.', 4),
('d8000000-0000-0000-0000-000000000017', 'E', 'Start oral corticosteroids as first-line treatment for post-laser macular oedema', false, 'Ruled out because oral corticosteroids are not standard first-line treatment for diabetic macular oedema (post-laser or otherwise); intravitreal anti-VEGF therapy is the preferred approach, reserving intravitreal (not oral) corticosteroids for select second-line scenarios.', 5),
('d8000000-0000-0000-0000-000000000018', 'A', 'Conclude that panretinal photocoagulation has failed permanently and no further laser can be of benefit', false, $x$Ruled out because incomplete or gap areas in peripheral treatment are a recognised cause of persistent neovascularisation, and supplementary laser to under-treated ischaemic areas often provides further benefit; concluding laser has 'failed permanently' would miss a treatable cause.$x$, 1),
('d8000000-0000-0000-0000-000000000018', 'B', 'Manage with topical corticosteroids alone, treating this as post-operative inflammation rather than neovascular glaucoma', false, 'Ruled out because gonioscopic confirmation of new vessels in the angle with markedly raised intraocular pressure indicates neovascular glaucoma, not simple postoperative inflammation; topical steroids alone would not address the underlying ischaemic neovascular process.', 2),
('d8000000-0000-0000-0000-000000000018', 'C', 'Repeat vitrectomy immediately as the sole next step without further laser or anti-VEGF therapy', false, 'Ruled out because addressing the ischaemic drive (with supplementary laser and/or anti-VEGF) and controlling intraocular pressure are the priority next steps; repeat vitrectomy is not the standard immediate response to post-vitrectomy neovascular glaucoma.', 3),
('d8000000-0000-0000-0000-000000000018', 'D', 'Assess for and treat any areas of retinal non-perfusion or under-treated peripheral retina with supplementary laser, alongside intravitreal anti-VEGF therapy and intraocular pressure-lowering treatment', true, 'Correct. Persistent or new neovascular glaucoma despite prior panretinal photocoagulation (including intraoperative endolaser) suggests incomplete peripheral retinal treatment or ongoing ischaemic drive, sometimes with areas difficult to treat completely at the time of vitrectomy (e.g. peripheral retina, especially anteriorly). Management involves careful re-assessment (often with wide-field imaging/fluorescein angiography) to identify and supplement any under-treated ischaemic retina with further laser, combined with intravitreal anti-VEGF therapy to more rapidly reduce the neovascular drive, and appropriate IOP-lowering treatment for the neovascular glaucoma itself.', 4),
('d8000000-0000-0000-0000-000000000018', 'E', 'Discontinue diabetes management input, as ocular neovascularisation at this stage is unrelated to glycaemic control', false, 'Ruled out because good glycaemic control remains relevant to overall diabetic retinopathy management and general prognosis, even though the acute priority is addressing the ischaemic retinal drive and intraocular pressure directly.', 5),
('d8000000-0000-0000-0000-000000000019', 'A', 'Continue standard annual screening intervals, as pregnancy does not affect diabetic retinopathy risk', false, 'Ruled out because pregnancy is a recognised independent risk factor for retinopathy progression, and standard annual intervals are inadequate during pregnancy; increased surveillance frequency is required.', 1),
('d8000000-0000-0000-0000-000000000019', 'B', 'Recommend she deliberately relax glycaemic control during pregnancy to slow retinopathy progression', false, 'Ruled out because deliberately worsening glycaemic control is harmful to both maternal retinopathy risk long-term and fetal outcomes; the correct approach is maintaining good glycaemic control while increasing surveillance frequency to detect and manage any progression early.', 2),
('d8000000-0000-0000-0000-000000000019', 'C', 'Discontinue eye screening until after delivery, as retinal treatment cannot be given during pregnancy in any circumstances', false, 'Ruled out because retinal treatments such as laser photocoagulation can be safely performed during pregnancy if needed for sight-threatening disease, and screening should continue (indeed increase) throughout pregnancy, not be paused until after delivery.', 3),
('d8000000-0000-0000-0000-000000000019', 'D', 'Arrange prophylactic panretinal photocoagulation now regardless of current disease stage, to pre-empt pregnancy-related progression', false, 'Ruled out because prophylactic PRP is not indicated for moderate non-proliferative disease without proliferative changes; the appropriate approach is increased surveillance to detect progression, with treatment given if and when disease reaches a treatment-requiring stage.', 4),
('d8000000-0000-0000-0000-000000000019', 'E', 'Arrange more frequent retinal screening throughout pregnancy (e.g. each trimester, or more often if retinopathy progresses), given the recognised risk of retinopathy progression associated with pregnancy and rapid glycaemic improvement', true, 'Correct. Pregnancy is an independent risk factor for progression of diabetic retinopathy, and rapid improvement in glycaemic control (as recommended for pregnancy) can paradoxically accelerate this progression in the short term, similar to the phenomenon of early worsening seen with rapid glycaemic correction generally. National guidance recommends increased surveillance frequency during pregnancy (typically each trimester, with more frequent review if retinopathy is more advanced or progressing), reflecting the higher risk in this specific context, rather than continuing pre-pregnancy screening intervals.', 5),
('d8000000-0000-0000-0000-000000000020', 'A', 'Observe with serial OCT every 6 months, as tractional detachment not yet involving the fovea does not require surgical intervention', false, 'Ruled out because although some stable, non-progressive tractional detachments distant from the macula can be observed, one actively threatening the fovea (within 500 micrometres) warrants timely surgical intervention rather than a prolonged observation interval, given the risk of progression to foveal involvement and worse visual outcomes.', 1),
('d8000000-0000-0000-0000-000000000020', 'B', 'Perform panretinal photocoagulation alone without vitrectomy, as laser addresses the traction directly', false, 'Ruled out because panretinal photocoagulation treats the ischaemic drive for neovascularisation but does not relieve existing mechanical vitreoretinal traction; vitrectomy is required to address the traction threatening the fovea.', 2),
('d8000000-0000-0000-0000-000000000020', 'C', 'Arrange vitrectomy surgery given the tractional detachment threatening the fovea, before foveal involvement occurs', true, 'Correct. Tractional retinal detachment from proliferative diabetic retinopathy that threatens but has not yet involved the fovea is an indication for vitrectomy, ideally performed before the fovea becomes involved, since visual prognosis is substantially better when surgery is undertaken prior to foveal detachment rather than after visual acuity has already deteriorated from macular involvement. Surgery addresses the vitreoretinal traction (membrane peel, relief of traction) and allows completion of panretinal photocoagulation as needed.', 3),
('d8000000-0000-0000-0000-000000000020', 'D', 'Start intravitreal anti-VEGF monotherapy as the sole treatment for the tractional detachment', false, 'Ruled out because anti-VEGF therapy alone does not relieve mechanical traction and can in some circumstances increase fibrovascular contraction risk if used without planned surgical intervention; while anti-VEGF may be used as an adjunct (e.g. pre-operatively to reduce intraoperative bleeding), it is not a substitute for vitrectomy in traction threatening the fovea.', 4),
('d8000000-0000-0000-0000-000000000020', 'E', 'Wait until the fovea is fully detached before considering vitrectomy, to confirm the detachment is progressive', false, 'Ruled out because waiting for foveal involvement worsens visual prognosis; surgery is best performed while the fovea is still threatened but not yet involved, to maximise visual outcome.', 5),
('d8000000-0000-0000-0000-000000000021', 'A', 'New tractional retinal detachment causing these symptoms, requiring urgent vitrectomy', false, 'Ruled out because gradual peripheral field constriction and night vision loss with preserved central acuity over 2 years, in a patient with previously extensive PRP, is more consistent with a recognised laser-related complication than an acute tractional detachment, which would typically present differently and be visible on fundoscopy/OCT.', 1),
('d8000000-0000-0000-0000-000000000021', 'B', 'Retinitis pigmentosa unrelated to his diabetes or previous treatment', false, 'Ruled out because in this clinical context (known extensive PRP, gradual symmetric-sounding peripheral loss following treatment), the most likely and directly relevant explanation is a recognised complication of panretinal photocoagulation rather than an unrelated inherited retinal dystrophy, though this could be considered if the history did not fit as well.', 2),
('d8000000-0000-0000-0000-000000000021', 'C', 'Vitamin A deficiency as the most likely cause, requiring supplementation', false, 'Ruled out because there is no described risk factor for vitamin A deficiency (e.g. malabsorption, bariatric surgery), and the clinical context of extensive prior PRP provides a much more likely explanation for these specific symptoms.', 3),
('d8000000-0000-0000-0000-000000000021', 'D', 'Peripheral visual field constriction and reduced night vision as a recognised long-term side effect of extensive panretinal photocoagulation, due to destruction of peripheral photoreceptors', true, 'Correct. Panretinal photocoagulation, while sight-saving for proliferative diabetic retinopathy, destroys peripheral retinal tissue (including rod photoreceptors important for night vision and peripheral field) as part of its therapeutic mechanism of reducing overall retinal oxygen demand and VEGF drive. Extensive or repeated PRP treatment is a recognised cause of peripheral visual field constriction and reduced night vision (nyctalopia), a trade-off accepted because it prevents more severe sight-threatening complications of proliferative disease; central acuity is typically preserved as the macula is spared from direct treatment.', 4),
('d8000000-0000-0000-0000-000000000021', 'E', 'Neovascular glaucoma causing progressive visual field loss', false, 'Ruled out because there is no mention of raised intraocular pressure, iris neovascularisation, or pain; the clinical picture described (peripheral field loss and nyctalopia after extensive PRP with preserved acuity) is explained by a known laser treatment effect rather than neovascular glaucoma.', 5),
('d8000000-0000-0000-0000-000000000022', 'A', 'Anti-VEGF therapy has no systemic absorption or systemic risk and can be given without any additional consideration', false, 'Ruled out because anti-VEGF agents do have some systemic absorption after intravitreal injection, and current safety data support at least a modest, clinically relevant signal for arterial thromboembolic events that should be discussed, particularly in high cardiovascular risk patients.', 1),
('d8000000-0000-0000-0000-000000000022', 'B', 'Anti-VEGF therapy is absolutely contraindicated in any patient with a myocardial infarction within the past 12 months', false, 'Ruled out because recent myocardial infarction is not an absolute contraindication to anti-VEGF therapy; rather it prompts a careful individualised risk-benefit discussion and closer awareness of the (small) increased thromboembolic risk, not automatic exclusion from treatment.', 2),
('d8000000-0000-0000-0000-000000000022', 'C', 'Anti-VEGF therapy can still be considered, but the small increased risk of arterial thromboembolic events (including further cardiovascular events) associated with systemic VEGF inhibition should be discussed, with close cardiology liaison and individualised risk-benefit assessment given her recent myocardial infarction', true, 'Correct. Intravitreal anti-VEGF agents undergo some systemic absorption, and clinical trial and pharmacovigilance data have raised a small but recognised signal for arterial thromboembolic events (including myocardial infarction and stroke) with anti-VEGF therapy, particularly relevant in patients with recent significant cardiovascular events. This does not mean anti-VEGF therapy is contraindicated, but an individualised risk-benefit discussion, ideally with cardiology input given her recent MI, is appropriate before proceeding, and this is a recognised area of nuanced decision-making in modern retinal therapeutics.', 3),
('d8000000-0000-0000-0000-000000000022', 'D', 'Recommend intravitreal corticosteroid therapy instead, as it carries no systemic cardiovascular risk of any kind and should always be preferred in cardiac patients', false, 'Ruled out because intravitreal corticosteroids carry their own risk profile (cataract, intraocular pressure elevation) and are not automatically preferred purely on cardiovascular grounds over anti-VEGF therapy, which remains first-line for centre-involving DMO; the correct approach is individualised discussion, not a blanket switch.', 4),
('d8000000-0000-0000-0000-000000000022', 'E', 'Delay any treatment for at least 5 years after a myocardial infarction before considering anti-VEGF therapy', false, 'Ruled out because there is no requirement for such a prolonged fixed delay; decisions are individualised based on ongoing cardiovascular risk and the urgency of treating sight-threatening macular oedema, not a rigid time-based exclusion.', 5),
('d8000000-0000-0000-0000-000000000023', 'A', 'These changes most likely represent early worsening of retinopathy associated with rapid glycaemic improvement; continue her current diabetes treatment and arrange closer-interval retinal review rather than stopping treatment', true, 'Correct. Rapid improvement in glycaemic control, regardless of the specific agent used to achieve it, can be associated with transient early worsening of diabetic retinopathy, and this is a well-documented phenomenon not specific to insulin therapy alone. The appropriate response is not to stop or reverse effective diabetes treatment, but to arrange closer ophthalmological surveillance to ensure any worsening remains self-limiting and does not progress to a sight-threatening stage requiring specific retinal treatment.', 1),
('d8000000-0000-0000-0000-000000000023', 'B', 'Discontinue the SGLT2 inhibitor immediately, as it is directly toxic to the retina', false, 'Ruled out because there is no evidence that SGLT2 inhibitors are directly retinotoxic; the retinal changes described are consistent with the known phenomenon of early worsening associated with rapid glycaemic improvement from any effective treatment, not a specific drug toxicity requiring cessation.', 2),
('d8000000-0000-0000-0000-000000000023', 'C', 'Reassure the patient that no further monitoring is needed, as these changes are of no clinical significance at any point', false, 'Ruled out because although early worsening is often transient and self-limiting, appropriate closer monitoring is still warranted to detect the minority of cases that progress further, rather than dismissing the changes entirely.', 3),
('d8000000-0000-0000-0000-000000000023', 'D', 'Arrange immediate panretinal photocoagulation given progression in retinopathy findings', false, 'Ruled out because moderate non-proliferative diabetic retinopathy with mild interval change does not meet criteria for panretinal photocoagulation, which is reserved for proliferative or high-risk disease; closer monitoring, not immediate laser, is appropriate here.', 4),
('d8000000-0000-0000-0000-000000000023', 'E', 'Advise her to deliberately allow her glucose control to worsen again to prevent further retinal changes', false, 'Ruled out because deliberately worsening glycaemic control is harmful overall and not the recommended response; the correct approach is maintaining good control while increasing retinal surveillance.', 5),
('d8000000-0000-0000-0000-000000000024', 'A', 'Stop all treatment and follow-up immediately, as 2 years of good response indicates the underlying disease has resolved permanently', false, 'Ruled out because diabetic macular oedema is a chronic condition related to ongoing diabetic vascular changes, and stopping treatment and monitoring abruptly risks unrecognised recurrence and visual decline; a structured extension of intervals with continued monitoring is safer.', 1),
('d8000000-0000-0000-0000-000000000024', 'B', 'Consider a cautious extension of treatment intervals (treat-and-extend approach) with close monitoring, rather than abrupt discontinuation, given the risk of oedema recurrence if treatment is simply stopped', true, 'Correct. In patients with a sustained, good anatomical and functional response to anti-VEGF therapy for diabetic macular oedema, a treat-and-extend approach allows cautious lengthening of the interval between injections while monitoring for recurrence, which can reduce treatment burden while minimising the risk of oedema recurrence and visual decline associated with abrupt cessation. Complete discontinuation without any monitoring plan risks unrecognised recurrence and visual loss, so a structured, gradual approach with agreed monitoring is preferred over simply stopping.', 2),
('d8000000-0000-0000-0000-000000000024', 'C', 'Continue the same 8-weekly interval indefinitely with no possibility of extension, regardless of sustained stability', false, 'Ruled out because sustained stability is precisely the situation in which cautious interval extension (treat-and-extend) should be considered to reduce treatment burden, rather than maintaining a fixed frequent interval indefinitely without adjustment.', 3),
('d8000000-0000-0000-0000-000000000024', 'D', 'Switch immediately to intravitreal corticosteroid implants purely to reduce visit frequency, regardless of current excellent response to anti-VEGF', false, 'Ruled out because switching therapy is not necessary when there is a sustained good response to the current anti-VEGF agent; a preferable initial approach is extending the treatment interval within the current effective therapy, reserving a switch in modality for non-response or intolerance.', 4),
('d8000000-0000-0000-0000-000000000024', 'E', 'Refer for immediate vitrectomy as an alternative to ongoing injections', false, 'Ruled out because vitrectomy is not an alternative treatment for diabetic macular oedema responding well to anti-VEGF therapy without vitreomacular traction; it is not indicated here and would not reduce treatment burden appropriately compared with interval extension.', 5),
('d8000000-0000-0000-0000-000000000025', 'A', 'Continue anti-VEGF monotherapy unchanged, as it is clearly superior to panretinal photocoagulation in all patients regardless of adherence', false, $x$Ruled out because anti-VEGF monotherapy and panretinal photocoagulation have comparable overall efficacy for proliferative disease in trial settings, but anti-VEGF's requirement for sustained follow-up is a critical practical vulnerability; in a patient demonstrating poor adherence, this makes panretinal photocoagulation (or combination treatment) the safer choice, not a default continuation of monotherapy.$x$, 1),
('d8000000-0000-0000-0000-000000000025', 'B', 'Discharge her from ophthalmology follow-up since missed appointments indicate she does not wish to engage with care', false, 'Ruled out because discharging a patient with active proliferative diabetic retinopathy on treatment risks preventable severe visual loss; the correct approach is to actively address the adherence risk by adapting the treatment strategy (e.g. towards panretinal photocoagulation), not to discontinue her care altogether.', 2),
('d8000000-0000-0000-0000-000000000025', 'C', 'Switch to intravitreal corticosteroid implants, as they require the least frequent monitoring of all available treatments for proliferative disease', false, 'Ruled out because intravitreal corticosteroids are not a standard or evidence-based treatment for proliferative diabetic retinopathy itself (their evidence base is in diabetic macular oedema); this would not appropriately address the underlying proliferative disease risk.', 3),
('d8000000-0000-0000-0000-000000000025', 'D', 'Reassure her that missed visits are of no clinical consequence provided she attends her injection appointments only', false, 'Ruled out because missed monitoring visits mean disease activity (and potentially progression to vitreous haemorrhage or tractional detachment) could go undetected between injections; this is a genuine safety concern that should be addressed proactively, not dismissed.', 4),
('d8000000-0000-0000-0000-000000000025', 'E', 'Anti-VEGF monotherapy for proliferative diabetic retinopathy requires strict adherence to a regular injection and monitoring schedule, so unreliable follow-up should prompt a discussion about converting to (or adding) panretinal photocoagulation, which provides a more durable treatment effect not dependent on repeated visits', true, 'Correct. While intravitreal anti-VEGF monotherapy is an evidence-based alternative to panretinal photocoagulation for proliferative diabetic retinopathy (e.g. per the Protocol S trial), it requires sustained, reliable adherence to frequent injections and monitoring, since disease can rapidly recur (including vision-threatening vitreous haemorrhage or tractional detachment) if treatment lapses. A patient demonstrating unreliable follow-up should have this risk explicitly discussed, with strong consideration given to adding or converting to panretinal photocoagulation, which provides a more durable, less follow-up-dependent treatment effect, better suited to patients at risk of loss to follow-up.', 5),
('d8000000-0000-0000-0000-000000000026', 'A', 'Start intravitreal anti-VEGF therapy immediately, as any diabetic macular oedema should be treated regardless of location or visual acuity', false, 'Ruled out because current management thresholds base treatment decisions on whether the centre of the macula is involved and whether visual acuity is affected; non-centre-involving oedema with normal acuity does not routinely require immediate anti-VEGF treatment, favouring closer monitoring instead.', 1),
('d8000000-0000-0000-0000-000000000026', 'B', 'Perform focal/grid laser photocoagulation immediately to the area of oedema regardless of visual acuity', false, 'Ruled out because immediate laser treatment is not required when acuity is unaffected and the centre is not involved; closer monitoring is the appropriate initial approach, reserving treatment for progression or centre involvement.', 2),
('d8000000-0000-0000-0000-000000000026', 'C', 'Continue close monitoring with more frequent review (rather than immediate treatment), since non-centre-involving macular oedema with preserved visual acuity does not automatically require intravitreal or laser treatment', true, 'Correct. Non-centre-involving diabetic macular oedema with preserved visual acuity does not meet the threshold for immediate active treatment (anti-VEGF or laser), since the visual prognosis without centre involvement is generally good and unnecessary treatment carries its own risks and burden. The appropriate approach is closer-interval monitoring than routine annual screening, to detect any progression towards centre involvement or visual acuity decline early, at which point treatment would become appropriate.', 3),
('d8000000-0000-0000-0000-000000000026', 'D', 'Discharge back to routine annual screening with no change in monitoring frequency', false, 'Ruled out because although immediate treatment is not required, simply reverting to standard annual screening would risk missing early progression to centre-involving oedema; closer-interval monitoring is more appropriate at this stage.', 4),
('d8000000-0000-0000-0000-000000000026', 'E', 'Arrange vitrectomy as a preventive measure to reduce the risk of progression to centre-involving oedema', false, 'Ruled out because vitrectomy has no established role as a preventive measure for non-centre-involving macular oedema without tractional features; monitoring is the appropriate approach at this stage.', 5),
('d8000000-0000-0000-0000-000000000027', 'A', 'Reassure him that nothing further can be done and continue treating each episode individually as it occurs indefinitely', false, 'Ruled out because frequent recurrences causing cumulative risk (synechiae, cataract, glaucoma) warrant consideration of preventive strategies beyond simply treating each episode as it arises, including prophylactic topical therapy or systemic options in refractory cases.', 1),
('d8000000-0000-0000-0000-000000000027', 'B', 'Start oral corticosteroids continuously as first-line prophylaxis for recurrent anterior uveitis', false, 'Ruled out because continuous oral corticosteroids carry substantial systemic side-effect burden and are not first-line for isolated recurrent anterior uveitis; topical prophylaxis or targeted systemic/biologic therapy (in refractory cases) are preferred over long-term oral steroids.', 2),
('d8000000-0000-0000-0000-000000000027', 'C', 'Recommend HLA-B27 testing repeated periodically, as a negative result would remove the need for any further management', false, 'Ruled out because HLA-B27 status does not change over time and repeat testing provides no additional clinical information; management should focus on reducing recurrence frequency, not repeating a fixed genetic test.', 3),
('d8000000-0000-0000-0000-000000000027', 'D', 'Arrange immediate enucleation of the affected eye to prevent further recurrent episodes', false, 'Ruled out because enucleation is a wildly disproportionate response to recurrent anterior uveitis, which is a manageable, treatable condition; this option is not a legitimate management strategy.', 4),
('d8000000-0000-0000-0000-000000000027', 'E', 'Consider long-term low-dose topical corticosteroid prophylaxis or, if recurrences continue to be frequent and disabling, discuss systemic immunosuppressive/biologic therapy with rheumatology', true, 'Correct. Frequent recurrent HLA-B27-associated anterior uveitis, despite adequate treatment of individual episodes, may warrant a step-up in management beyond episodic treatment: options include a trial of long-term low-dose topical corticosteroid prophylaxis (accepting the trade-off of steroid-related complications with monitoring), and for those with frequent, disabling recurrences, joint rheumatology discussion regarding systemic immunosuppression or biologic therapy (e.g. TNF-alpha inhibitors, particularly adalimumab, which has evidence in recurrent anterior uveitis) to reduce recurrence frequency and long-term complications such as synechiae and cataract.', 5),
('d8000000-0000-0000-0000-000000000028', 'A', 'Increase the frequency and potency of topical corticosteroids alone, as this should adequately treat posterior segment inflammation with time', false, 'Ruled out because topical corticosteroids have poor posterior segment penetration and are inadequate for treating vitritis, periphlebitis or macular oedema; systemic or local (periocular/intravitreal) therapy with better posterior segment reach is required.', 1),
('d8000000-0000-0000-0000-000000000028', 'B', 'Arrange immediate pars plana vitrectomy as first-line treatment for the vitreous inflammation', false, 'Ruled out because vitrectomy is not first-line management for active sarcoid panuveitis; medical anti-inflammatory therapy (systemic corticosteroids ± steroid-sparing agents) is the appropriate initial approach, with surgery reserved for specific complications (e.g. non-clearing vitreous debris, epiretinal membrane) rather than active inflammation.', 2),
('d8000000-0000-0000-0000-000000000028', 'C', 'Withhold any further treatment since her hilar lymphadenopathy is stable, indicating the disease is quiescent', false, 'Ruled out because systemic disease stability (stable hilar lymphadenopathy) does not equate to ocular disease control; active panuveitis with macular oedema requires targeted treatment regardless of the chest CT findings.', 3),
('d8000000-0000-0000-0000-000000000028', 'D', 'Start systemic corticosteroid therapy (oral or, if severe, periocular/intravitreal corticosteroid as an adjunct), given posterior segment involvement and macular oedema inadequately controlled by topical treatment alone', true, 'Correct. Sarcoid panuveitis with significant posterior segment involvement (vitritis, periphlebitis, macular oedema) is not adequately treated by topical corticosteroids alone, since these have minimal posterior segment penetration. Systemic corticosteroid therapy (oral prednisolone, or in severe/localised cases, periocular or intravitreal corticosteroid injections) is required to control posterior inflammation and treat associated macular oedema, with steroid-sparing systemic immunosuppression considered if a prolonged course or steroid dependence develops.', 4),
('d8000000-0000-0000-0000-000000000028', 'E', 'Start a biologic agent (e.g. anti-TNF) immediately as first-line therapy, bypassing corticosteroids', false, 'Ruled out because corticosteroids (systemic ± local) remain first-line for active sarcoid uveitis; biologic therapy is generally reserved for steroid-refractory or steroid-dependent cases, not used as an initial first-line choice ahead of corticosteroids.', 5),
('d8000000-0000-0000-0000-000000000029', 'A', 'Escalate to biologic therapy (e.g. an anti-TNF agent such as infliximab or adalimumab, or interferon-alpha) given recurrent sight-threatening flares despite conventional immunosuppression', true, $x$Correct. Behçet's disease with recurrent sight-threatening posterior/panuveitis and retinal vasculitis, breaking through conventional immunosuppression (azathioprine and corticosteroids), is an indication to escalate to biologic therapy. Anti-TNF agents (infliximab and adalimumab have the strongest evidence base) or interferon-alpha are established options for refractory Behçet's uveitis and are recognised to reduce flare frequency and preserve vision, reflecting current international treatment recommendations for severe ocular Behçet's disease.$x$, 1),
('d8000000-0000-0000-0000-000000000029', 'B', 'Increase the dose of oral prednisolone alone to a very high maintenance dose indefinitely, without adding further therapy', false, $x$Ruled out because high-dose long-term corticosteroids carry substantial toxicity and are not an appropriate long-term strategy for recurrent flares; escalation to steroid-sparing biologic therapy is the recommended approach for refractory Behçet's uveitis.$x$, 2),
('d8000000-0000-0000-0000-000000000029', 'C', 'Switch from azathioprine to a second-line conventional agent such as methotrexate alone, without considering biologic therapy', false, $x$Ruled out because in Behçet's uveitis with recurrent sight-threatening flares on established conventional immunosuppression, biologic therapy (particularly anti-TNF agents) has a stronger evidence base and is the recommended escalation, rather than simply cycling through conventional agents.$x$, 3),
('d8000000-0000-0000-0000-000000000029', 'D', 'Arrange enucleation of the worse eye to prevent further flares affecting the better eye', false, 'Ruled out because enucleation is not an appropriate treatment for recurrent uveitis; effective systemic escalation therapy exists and should be tried before considering such a drastic and inappropriate step.', 4),
('d8000000-0000-0000-0000-000000000029', 'E', $x$Discontinue all immunosuppression, as Behçet's disease uveitis typically burns out and does not require escalation$x$, false, $x$Ruled out because Behçet's uveitis can cause severe, cumulative, sight-threatening damage through recurrent vasculitic flares, and stopping immunosuppression in the face of recurrent flares would risk further irreversible visual loss rather than 'burning out' safely.$x$, 5),
('d8000000-0000-0000-0000-000000000030', 'A', 'Since she is asymptomatic, no treatment escalation or closer monitoring is required regardless of anterior chamber findings', false, 'Ruled out because active anterior chamber inflammation (2+ cells) still requires treatment and closer monitoring even without symptoms, since ongoing subclinical inflammation drives further cumulative damage; asymptomatic status should not be equated with inactive disease.', 1),
('d8000000-0000-0000-0000-000000000030', 'B', 'Chronic anterior uveitis associated with juvenile idiopathic arthritis is frequently asymptomatic despite active inflammation, making regular screening (even in a quiet-looking eye) essential to detect and treat disease activity before complications such as band keratopathy, cataract, and glaucoma develop further', true, $x$Correct. A key and distinctive feature of JIA-associated uveitis is that it is characteristically asymptomatic or minimally symptomatic (unlike HLA-B27-associated acute anterior uveitis, which is typically painful and photophobic), meaning a 'quiet' white eye can conceal significant ongoing inflammation. This underlies the rationale for structured, regular screening programmes in children and young people with JIA, since without screening, damage (band keratopathy, cataract, glaucoma, synechiae) can accumulate silently before symptoms prompt review; ongoing regular screening and treatment escalation as needed remain essential even once significant chronic complications have developed.$x$, 2),
('d8000000-0000-0000-0000-000000000030', 'C', 'The presence of band keratopathy and cataract indicates the disease is now burnt out and further treatment is unnecessary', false, 'Ruled out because these findings reflect cumulative damage from previous inflammation and treatment, not evidence that current inflammation (2+ cells, new keratic precipitates) is inactive; active inflammation still requires management regardless of pre-existing structural damage.', 3),
('d8000000-0000-0000-0000-000000000030', 'D', 'This presentation is inconsistent with JIA-associated uveitis, which always presents with a painful red eye', false, 'Ruled out because this statement is factually incorrect; JIA-associated uveitis is characteristically asymptomatic/minimally symptomatic, which is precisely why regular screening (rather than reliance on symptoms) is central to its management.', 4),
('d8000000-0000-0000-0000-000000000030', 'E', 'Methotrexate should be stopped immediately since disease activity has been detected despite treatment', false, 'Ruled out because detecting breakthrough inflammation on methotrexate would prompt consideration of treatment escalation (e.g. adding a biologic) or optimisation, not simply stopping the existing steroid-sparing agent outright.', 5),
('d8000000-0000-0000-0000-000000000031', 'A', 'Start topical antibiotics alone and review again in 48 hours before considering intravitreal treatment', false, 'Ruled out because topical antibiotics achieve inadequate intraocular concentrations to treat endophthalmitis; immediate intravitreal antibiotic administration (after sampling) is required given the rapid, sight-threatening course of this condition, not a delayed topical-only approach.', 1),
('d8000000-0000-0000-0000-000000000031', 'B', 'Arrange oral antibiotics as monotherapy while awaiting outpatient ophthalmology review', false, 'Ruled out because oral antibiotics do not achieve adequate intravitreal concentrations for treating endophthalmitis, and this is an emergency requiring immediate same-day intravitreal treatment, not outpatient deferral.', 2),
('d8000000-0000-0000-0000-000000000031', 'C', 'Perform immediate pars plana vitrectomy in all cases regardless of presenting visual acuity, bypassing intravitreal antibiotic tap-and-inject', false, 'Ruled out because initial management is tap-and-inject (vitreous/aqueous sampling with immediate intravitreal antibiotics); immediate vitrectomy is reserved based on presenting visual acuity (e.g. perception of light only, per Endophthalmitis Vitrectomy Study criteria) rather than performed in all cases as the very first step.', 3),
('d8000000-0000-0000-0000-000000000031', 'D', 'Manage with observation alone, as postoperative inflammation typically resolves without specific treatment', false, 'Ruled out because this clinical picture (hypopyon, marked vitritis, rapid visual decline post-surgery) represents likely infectious endophthalmitis, a medical emergency requiring immediate sampling and intravitreal antibiotic treatment, not simple observation.', 4),
('d8000000-0000-0000-0000-000000000031', 'E', 'Arrange emergency vitreous and aqueous tap for microbiological sampling, followed immediately by empirical intravitreal antibiotics (e.g. vancomycin and ceftazidime), without waiting for culture results', true, 'Correct. Acute-onset painful panuveitis with hypopyon and vitritis in the days following intraocular surgery is acute postoperative endophthalmitis until proven otherwise, a sight-threatening emergency requiring immediate action. Standard management is urgent vitreous (and aqueous) sampling for microbiology, followed immediately by empirical broad-spectrum intravitreal antibiotics (typically vancomycin for gram-positive and ceftazidime for gram-negative cover) without waiting for culture confirmation, given the rapid, sight-threatening course of this condition; further management (e.g. vitrectomy) is guided by initial visual acuity and response to treatment, per evidence such as the Endophthalmitis Vitrectomy Study.', 5),
('d8000000-0000-0000-0000-000000000032', 'A', 'Continue mycophenolate unchanged, as birdshot chorioretinopathy does not require escalation once any systemic treatment is started', false, 'Ruled out because ongoing disease progression on adequate mycophenolate therapy (new lesions, ERG deterioration, worsening symptoms) indicates inadequate disease control, requiring escalation rather than continuation of an insufficiently effective regimen.', 1),
('d8000000-0000-0000-0000-000000000032', 'B', 'Discontinue immunosuppression, as ERG changes indicate irreversible disease unresponsive to any treatment', false, 'Ruled out because escalating rather than discontinuing immunosuppression is the appropriate response to progressive birdshot chorioretinopathy, since further treatment can still preserve remaining retinal function even after some functional decline has occurred.', 2),
('d8000000-0000-0000-0000-000000000032', 'C', 'Arrange panretinal photocoagulation as the primary treatment for the choroidal lesions', false, 'Ruled out because birdshot chorioretinopathy is an autoimmune inflammatory chorioretinopathy, not primarily an ischaemic/neovascular process requiring panretinal photocoagulation; management is through systemic immunosuppression, not retinal laser.', 3),
('d8000000-0000-0000-0000-000000000032', 'D', 'Escalate systemic immunosuppression (e.g. adding or switching to a biologic agent such as an anti-TNF agent, or combination immunosuppression) given clinical and electrophysiological evidence of disease progression despite mycophenolate', true, 'Correct. Birdshot chorioretinopathy is monitored using a combination of clinical findings, imaging, and objective electroretinogram (ERG) parameters, since progressive photoreceptor/retinal dysfunction can occur even when the fundus appears relatively unremarkable, and ERG decline is a recognised marker of disease progression requiring treatment escalation. Breakthrough disease activity (new lesions, worsening ERG, worsening visual field and nyctalopia) despite adequate mycophenolate therapy is an indication to escalate immunosuppression, with biologic therapy (anti-TNF agents) increasingly used in refractory birdshot disease to preserve retinal function and prevent further visual field loss.', 4),
('d8000000-0000-0000-0000-000000000032', 'E', 'Repeat HLA-A29 testing to confirm ongoing disease association before considering any treatment change', false, 'Ruled out because HLA-A29 status does not change over time and offers no additional information relevant to monitoring disease activity or guiding treatment escalation decisions; ERG and clinical/imaging findings, not repeat genetic testing, guide management here.', 5),
('d8000000-0000-0000-0000-000000000033', 'A', 'Treat the uveitis with topical corticosteroids alone and reassure him that back pain is unrelated and needs no further assessment', false, 'Ruled out because his back pain history has classic inflammatory features (age of onset, morning stiffness relieved by exercise, chronicity) strongly suggesting axial spondyloarthritis, an association well recognised with recurrent anterior uveitis; this needs rheumatological assessment, not dismissal.', 1),
('d8000000-0000-0000-0000-000000000033', 'B', 'Start oral corticosteroids as first-line treatment for this episode of anterior uveitis', false, 'Ruled out because isolated anterior uveitis without posterior segment involvement is typically managed with topical (not oral) corticosteroids and cycloplegics as first-line treatment; oral steroids are reserved for more severe or refractory cases or posterior/panuveitis.', 2),
('d8000000-0000-0000-0000-000000000033', 'C', 'Treat the acute uveitis with intensive topical corticosteroids and cycloplegics, and refer for rheumatological assessment for possible axial spondyloarthritis given his inflammatory back pain history', true, 'Correct. Recurrent acute unilateral anterior uveitis with a history of chronic inflammatory-sounding back pain (insidious onset, morning stiffness improving with exercise, duration over 3 months, age of onset under 40) should prompt screening for axial spondyloarthritis (including ankylosing spondylitis), given the well-established association between HLA-B27-related acute anterior uveitis and spondyloarthropathies. The acute uveitis itself is treated in standard fashion with topical corticosteroids and cycloplegics, but rheumatological referral is an important parallel step to identify and manage any underlying systemic inflammatory disease, which has its own treatment implications and complication risks.', 3),
('d8000000-0000-0000-0000-000000000033', 'D', 'Arrange HLA-B27 testing but withhold any uveitis treatment until the result is available', false, 'Ruled out because acute anterior uveitis should be treated promptly with topical corticosteroids and cycloplegics regardless of HLA-B27 result, which does not need to delay treatment; HLA-B27 testing may be a useful adjunct to support the systemic diagnosis but treatment should proceed without delay.', 4),
('d8000000-0000-0000-0000-000000000033', 'E', 'Refer directly for orbital MRI as the priority investigation before treating the uveitis', false, 'Ruled out because orbital MRI is not indicated for typical anterior uveitis without other red flag features (e.g. proptosis, optic nerve signs); the priority is treating the uveitis and pursuing rheumatological assessment for the systemic association, not orbital imaging.', 5),
('d8000000-0000-0000-0000-000000000034', 'A', 'Stop the corticosteroid drops immediately and abruptly, as this is the only way to lower intraocular pressure', false, 'Ruled out because abrupt cessation of corticosteroids risks rebound uveitis recurrence; a gradual, monitored taper (alongside starting pressure-lowering treatment) is the safer approach to balance both risks.', 1),
('d8000000-0000-0000-0000-000000000034', 'B', 'Start topical intraocular pressure-lowering treatment and begin a gradual taper of the topical corticosteroid to the lowest effective dose (or switch to a lower-potency/lower-penetration steroid) while monitoring for uveitis recurrence', true, $x$Correct. This is steroid-induced ocular hypertension ('steroid response'), a recognised complication of topical corticosteroid use for uveitis, particularly with potent agents like dexamethasone. Management involves starting pressure-lowering treatment to protect the optic nerve, alongside a careful, gradual reduction of the corticosteroid to the lowest dose that controls inflammation (or switching to an agent with a lower propensity to raise pressure, such as fluorometholone or loteprednol), balancing the competing risks of glaucomatous damage against uveitis recurrence if steroids are withdrawn too quickly.$x$, 2),
('d8000000-0000-0000-0000-000000000034', 'C', 'Continue the same corticosteroid regimen unchanged, as intraocular pressure elevation is not clinically significant in uveitis patients', false, 'Ruled out because new pressure elevation with early glaucomatous optic disc changes is clinically significant and requires active intervention (pressure-lowering treatment and steroid tapering), not being dismissed as insignificant.', 3),
('d8000000-0000-0000-0000-000000000034', 'D', 'Proceed directly to trabeculectomy as the first-line intervention for this pressure rise', false, 'Ruled out because incisional glaucoma surgery is not first-line for steroid-induced ocular hypertension; medical pressure-lowering treatment combined with steroid tapering/switching is the appropriate initial approach, reserving surgery for cases refractory to these measures.', 4),
('d8000000-0000-0000-0000-000000000034', 'E', 'Add a second potent topical corticosteroid to further suppress inflammation and ignore the intraocular pressure findings', false, 'Ruled out because adding further corticosteroid would likely worsen the steroid-induced pressure rise and risks further optic nerve damage; the priority is treating the pressure rise and tapering steroid exposure, not intensifying it.', 5),
('d8000000-0000-0000-0000-000000000035', 'A', 'Start systemic (and consider adjunctive intravitreal) anti-CMV antiviral therapy (e.g. valganciclovir), alongside urgent engagement with HIV services to optimise antiretroviral therapy and immune reconstitution', true, 'Correct. This presentation (progressive, relatively painless retinitis with granular haemorrhagic infiltrate following the vascular arcades, minimal vitritis, in a patient with advanced HIV/AIDS and profound CD4 lymphopenia) is classic for cytomegalovirus (CMV) retinitis. Treatment requires systemic anti-CMV antiviral therapy (oral valganciclovir is now standard, with intravenous ganciclovir or intravitreal therapy considered for more severe/vision-threatening disease), alongside urgent re-engagement with HIV services to restart/optimise antiretroviral therapy, since immune reconstitution is critical to long-term control, while being aware of the risk of immune reconstitution uveitis if ART is started very abruptly in the context of active untreated CMV retinitis.', 1),
('d8000000-0000-0000-0000-000000000035', 'B', 'Start topical corticosteroids as first-line treatment, since minimal vitreous inflammation suggests a primarily anterior process', false, 'Ruled out because this is a posterior segment infectious retinitis (CMV), not primarily anterior uveitis; topical corticosteroids would not address the underlying viral infection and could worsen an infectious process if used inappropriately without antiviral cover.', 2),
('d8000000-0000-0000-0000-000000000035', 'C', 'Reassure the patient that this represents typical HIV-related retinal microvasculopathy (cotton wool spots) requiring no specific treatment', false, $x$Ruled out because the described findings (full-thickness necrosis, granular haemorrhagic 'pizza pie' appearance, progressive visual decline) are consistent with sight-threatening CMV retinitis, not benign HIV microvasculopathy (which typically shows only cotton wool spots without necrosis or progression), and require urgent antiviral treatment.$x$, 3),
('d8000000-0000-0000-0000-000000000035', 'D', 'Arrange emergency vitrectomy as the primary treatment for this presentation', false, 'Ruled out because CMV retinitis is treated primarily with systemic (± intravitreal) antiviral therapy, not vitrectomy, which is reserved for specific complications (e.g. retinal detachment) rather than as first-line treatment of active retinitis.', 4),
('d8000000-0000-0000-0000-000000000035', 'E', 'Delay any treatment until CD4 count improves with antiretroviral therapy over several months', false, 'Ruled out because CMV retinitis is a sight-threatening emergency requiring immediate antiviral treatment; delaying treatment for months while awaiting immune reconstitution risks irreversible visual loss and retinal detachment from progressive necrosis.', 5),
('d8000000-0000-0000-0000-000000000036', 'A', 'Treat as necrotising scleritis with urgent systemic immunosuppression (typically high-dose oral or IV corticosteroids with steroid-sparing agents, in liaison with rheumatology), given the risk of scleral perforation and its association with systemic vasculitic disease activity', true, 'Correct. Necrotising scleritis (non-blanching deep vascular injection, severe pain, scleral thinning with visible uvea) in a patient with longstanding rheumatoid arthritis is a marker of severe systemic disease activity and carries a significant risk of scleral perforation and even mortality if untreated, reflecting an underlying vasculitic process. Management requires urgent systemic immunosuppression (often high-dose corticosteroids as initial therapy, combined with escalation or optimisation of steroid-sparing/biologic therapy), with close rheumatology involvement given both the ocular and systemic disease implications; this is distinct from milder episcleritis or non-necrotising scleritis, which may be managed with topical or oral NSAIDs alone.', 1),
('d8000000-0000-0000-0000-000000000036', 'B', 'Manage with topical corticosteroid drops alone, as this is likely episcleritis which resolves with mild topical treatment', false, 'Ruled out because non-blanching deep vessel injection with scleral thinning and visible uvea indicates necrotising scleritis, not episcleritis (which shows blanching superficial vessels and is typically self-limiting); this requires urgent systemic treatment, not topical therapy alone.', 2),
('d8000000-0000-0000-0000-000000000036', 'C', 'Reassure the patient that no treatment is required since visual acuity is currently unaffected', false, 'Ruled out because necrotising scleritis carries a high risk of scleral perforation and is a marker of severe systemic vasculitic disease, regardless of current visual acuity; urgent treatment is required to prevent structural and systemic complications.', 3),
('d8000000-0000-0000-0000-000000000036', 'D', 'Arrange scleral patch grafting as the first-line and only necessary intervention', false, 'Ruled out because surgical scleral grafting is reserved for impending or actual perforation as an adjunct, not as first-line treatment; the priority is urgent systemic immunosuppression to control the underlying inflammatory/vasculitic process.', 4),
('d8000000-0000-0000-0000-000000000036', 'E', 'Stop her biologic therapy immediately, as it is the most likely cause of this eye finding', false, 'Ruled out because necrotising scleritis in this context reflects breakthrough systemic rheumatoid vasculitic disease activity rather than a typical adverse effect of biologic therapy; stopping her biologic is not the appropriate first response and may worsen systemic disease control, whereas urgent immunosuppressive escalation (in conjunction with rheumatology) is indicated.', 5),
('d8000000-0000-0000-0000-000000000037', 'A', 'Perform emergency enucleation of the injured left eye as the priority intervention, as this will reliably reverse the inflammation in the right eye', false, $x$Ruled out because once sympathetic ophthalmia has already developed in the fellow eye, enucleating the originally injured eye does not reliably improve or reverse the inflammatory process in the sympathising eye; the priority at this stage is systemic immunosuppression to protect vision, with enucleation decisions considered separately based on the injured eye's own prognosis.$x$, 1),
('d8000000-0000-0000-0000-000000000037', 'B', 'Treat with topical corticosteroids alone, as this is a localised anterior uveitis confined to the site of injury', false, 'Ruled out because this is bilateral panuveitis (including the previously uninjured eye) with posterior segment involvement (serous retinal detachments), which requires systemic (not merely topical) immunosuppression; topical treatment alone would be inadequate.', 2),
('d8000000-0000-0000-0000-000000000037', 'C', $x$Start urgent high-dose systemic corticosteroids with steroid-sparing immunosuppression as needed, and discuss the injured eye's visual potential with the patient regarding possible enucleation, recognising that once sympathetic ophthalmia has developed enucleation of the injured eye does not reliably improve outcomes in the sympathising eye$x$, true, $x$Correct. This presentation (bilateral granulomatous panuveitis with serous retinal detachments and vitiligo-like skin changes, following penetrating injury/intraocular surgery to one eye, with new inflammation in the previously uninjured 'sympathising' eye) is classic for sympathetic ophthalmia. Once sympathetic ophthalmia has developed, management is with aggressive systemic immunosuppression (high-dose corticosteroids, escalating to steroid-sparing agents as needed) to protect the sympathising eye's vision; enucleation of the injured (exciting) eye is a preventive measure ideally considered within the first 2 weeks after severe injury before sympathetic ophthalmia develops, but once the condition has already manifested, enucleating the injured eye does not reliably alter the course of disease in the fellow eye and the decision becomes primarily about the visual potential and comfort of the injured eye itself, not disease prevention.$x$, 3),
('d8000000-0000-0000-0000-000000000037', 'D', 'Reassure the patient that inflammation in the uninjured eye is coincidental and unrelated to the injury, requiring no specific treatment', false, 'Ruled out because new granulomatous panuveitis in the previously uninjured eye following penetrating injury/intraocular surgery to the fellow eye is the defining feature of sympathetic ophthalmia and requires urgent systemic treatment, not reassurance that it is unrelated.', 4),
('d8000000-0000-0000-0000-000000000037', 'E', 'Arrange skin biopsy of the vitiligo-like lesions as the priority investigation before considering any ocular treatment', false, 'Ruled out because the priority is urgent systemic immunosuppressive treatment to protect vision in the sympathising eye; the vitiligo-like skin changes support the clinical diagnosis (part of the Vogt-Koyanagi-Harada-like spectrum of findings sometimes seen with sympathetic ophthalmia) but a skin biopsy is not the priority action and should not delay treatment.', 5),
('d8000000-0000-0000-0000-000000000038', 'A', 'Prolonged tapering is simply a precaution against steroid withdrawal (Addisonian-type) crisis and has no bearing on the eye disease itself', false, 'Ruled out because although abrupt cessation of long-term corticosteroids can risk adrenal insufficiency, the specific rationale for prolonged slow tapering in VKH disease is to prevent recurrence and chronic progression of the ocular inflammatory disease itself, which is the primary clinical driver of this strategy in this condition.', 1),
('d8000000-0000-0000-0000-000000000038', 'B', $x$Rapid corticosteroid tapering in VKH disease is associated with a high risk of recurrence and progression to a chronic recurrent ('sunset glow fundus') phase with worse long-term visual outcomes, so a prolonged slow taper over at least 6 months is recommended to maintain disease suppression$x$, true, $x$Correct. A well-established principle in Vogt-Koyanagi-Harada disease management is that inadequate treatment duration or overly rapid corticosteroid tapering is strongly associated with progression from the acute uveitic phase to a chronic recurrent phase, characterised by the classic depigmented 'sunset glow fundus', recurrent granulomatous anterior uveitis, and a substantially worse long-term visual prognosis. Current recommendations therefore favour high-dose initial corticosteroid therapy maintained for a prolonged period with a slow, gradual taper (often over 6 months or longer), sometimes combined with early steroid-sparing immunosuppression, specifically to prevent this chronic recurrent transition.$x$, 2),
('d8000000-0000-0000-0000-000000000038', 'C', 'A slow taper is used because VKH disease always requires lifelong corticosteroid therapy with no possibility of eventual discontinuation', false, 'Ruled out because the goal of the prolonged taper is to eventually discontinue corticosteroids while avoiding recurrence, not to imply that lifelong therapy is mandatory in every case; some patients may successfully discontinue treatment after an adequately prolonged, gradual course.', 3),
('d8000000-0000-0000-0000-000000000038', 'D', 'Rapid tapering is preferred in VKH disease and this management plan represents an overly cautious, non-standard approach', false, 'Ruled out because this statement is incorrect; current evidence and expert consensus specifically favour prolonged, slow corticosteroid tapering in VKH disease because rapid tapering is associated with an increased risk of recurrence and chronic disease.', 4),
('d8000000-0000-0000-0000-000000000038', 'E', 'The tapering strategy is unrelated to the eye disease and is solely to manage her tinnitus and alopecia', false, 'Ruled out because although VKH is a systemic syndrome with these associated features, the specific rationale for prolonged corticosteroid tapering relates primarily to preventing recurrence and chronicity of the granulomatous panuveitis itself.', 5),
('d8000000-0000-0000-0000-000000000039', 'A', 'Reassure the patient that this represents a typical microvascular third nerve palsy given his vasculopathic risk factors, and arrange routine outpatient follow-up in 6 weeks', false, 'Ruled out because pupillary involvement (rather than pupil sparing) raises significant concern for a compressive aneurysmal cause even in a patient with vasculopathic risk factors, and requires urgent imaging rather than routine deferred follow-up, given the risk of rupture.', 1),
('d8000000-0000-0000-0000-000000000039', 'B', 'Start high-dose corticosteroids empirically for presumed inflammatory cranial neuropathy', false, 'Ruled out because there is no indication here of an inflammatory cause, and empirical corticosteroids would not be appropriate before excluding a compressive aneurysm, which is the priority given pupil involvement.', 2),
('d8000000-0000-0000-0000-000000000039', 'C', 'Arrange lumbar puncture as the first investigation to look for subarachnoid blood', false, 'Ruled out because the priority in a pupil-involving third nerve palsy is urgent vascular imaging (CT/MR angiography) to look for a compressive aneurysm directly; lumbar puncture is not the first-line investigation for this presentation, though it may have a role in different specific clinical contexts (e.g. suspected subarachnoid haemorrhage with a normal initial CT).', 3),
('d8000000-0000-0000-0000-000000000039', 'D', 'Arrange urgent CT or MR angiography to exclude a compressive posterior communicating artery aneurysm, given pupillary involvement in this third nerve palsy', true, $x$Correct. A third nerve palsy with pupillary involvement (anisocoria with a sluggish, larger pupil on the affected side) is considered a compressive lesion (most importantly a posterior communicating artery aneurysm) until proven otherwise, and requires urgent vascular imaging (CT angiography or MR angiography) to exclude this, given the risk of aneurysm rupture and subarachnoid haemorrhage if missed. This contrasts with a 'pupil-sparing' third nerve palsy in a vasculopathic patient, which is more often attributed to microvascular ischaemia and may be managed with risk factor optimisation and observation, though even pupil-sparing palsies warrant careful early monitoring.$x$, 4),
('d8000000-0000-0000-0000-000000000039', 'E', 'Refer for optic nerve sheath fenestration given the pupillary abnormality', false, 'Ruled out because optic nerve sheath fenestration is a treatment for optic nerve compression/raised intracranial pressure protection, not relevant to a third nerve palsy; the priority here is urgent vascular imaging to exclude aneurysmal compression.', 5),
('d8000000-0000-0000-0000-000000000040', 'A', 'Reassure the patient that since vision has fully recovered and fundoscopy is normal, no further action is required', false, 'Ruled out because amaurosis fugax, despite full visual recovery, represents a TIA-equivalent event carrying significant short-term stroke risk and requires urgent assessment, not reassurance alone.', 1),
('d8000000-0000-0000-0000-000000000040', 'B', 'Arrange routine (non-urgent) neurology outpatient referral within the next 4-6 weeks', false, 'Ruled out because amaurosis fugax requires same-day urgent assessment via a TIA pathway given the high short-term stroke risk, not routine outpatient referral over weeks.', 2),
('d8000000-0000-0000-0000-000000000040', 'C', 'Start therapeutic anticoagulation immediately without further specialist assessment, given her atrial fibrillation', false, 'Ruled out because she has a specific contraindication (previous gastrointestinal bleeding) requiring careful specialist risk-benefit assessment (potentially including left atrial appendage occlusion or other strategies) rather than simply starting anticoagulation without full assessment; this decision should be made as part of urgent specialist review, not empirically in isolation.', 3),
('d8000000-0000-0000-0000-000000000040', 'D', 'Perform intravitreal anti-VEGF injection as a precaution against future retinal artery occlusion', false, 'Ruled out because there is no role for anti-VEGF therapy in preventing or treating transient retinal ischaemia; the priority is systemic stroke risk assessment and secondary prevention, not intravitreal treatment.', 4),
('d8000000-0000-0000-0000-000000000040', 'E', 'Manage as a transient ischaemic attack (amaurosis fugax) with urgent same-day assessment via a rapid-access TIA/stroke pathway, including carotid imaging and cardiovascular risk assessment', true, 'Correct. Transient monocular visual loss (amaurosis fugax) represents a retinal transient ischaemic attack and carries a similarly high short-term risk of subsequent stroke as other TIA presentations, particularly in a patient with atrial fibrillation as a likely embolic source. Current guidance (e.g. NICE) recommends urgent same-day specialist assessment via a rapid-access TIA pathway, with carotid imaging (to assess for carotid stenosis amenable to endarterectomy/stenting) and full cardiovascular risk assessment, since the ABCD2-type risk stratification for amaurosis fugax should still prompt urgent action rather than routine follow-up.', 5),
('d8000000-0000-0000-0000-000000000041', 'A', 'The sixth nerve palsy indicates a separate structural lesion compressing the nerve, requiring dedicated cranial nerve imaging distinct from the IIH workup', false, 'Ruled out because in the context of confirmed raised intracranial pressure with an already normal MRI/MRV, an isolated sixth nerve palsy is a recognised false localising sign of the raised pressure itself, not evidence of an additional separate compressive lesion requiring further distinct imaging.', 1),
('d8000000-0000-0000-0000-000000000041', 'B', 'The sixth nerve palsy suggests a diagnosis alternative to IIH, such as myasthenia gravis, and acetylcholine receptor antibody testing should be the priority', false, 'Ruled out because the combination of papilloedema, raised CSF opening pressure and typical demographic strongly supports IIH as the unifying diagnosis, with the sixth nerve palsy explained as a false localising sign of raised pressure rather than pointing towards an unrelated neuromuscular junction disorder.', 2),
('d8000000-0000-0000-0000-000000000041', 'C', $x$The sixth nerve palsy is a recognised 'false localising sign' of raised intracranial pressure in idiopathic intracranial hypertension, and should improve with effective treatment of the underlying condition (e.g. acetazolamide and weight management) rather than requiring separate localised investigation$x$, true, $x$Correct. A unilateral or bilateral sixth (abducens) nerve palsy is a well-recognised 'false localising sign' in raised intracranial pressure of any cause, including idiopathic intracranial hypertension, because the long intracranial course of the abducens nerve makes it particularly vulnerable to stretch/compression from raised pressure, without indicating a separate structural lesion along its course. In this context (confirmed IIH with normal MRI/MRV and typical CSF opening pressure), the sixth nerve palsy is best explained as a consequence of raised intracranial pressure itself, and the focus of management is treating the underlying IIH, with resolution of the diplopia expected as intracranial pressure is controlled.$x$, 3),
('d8000000-0000-0000-0000-000000000041', 'D', 'The sixth nerve palsy is unrelated to her intracranial pressure and requires urgent surgical decompression of the nerve itself', false, 'Ruled out because the sixth nerve palsy here is a consequence of raised intracranial pressure (a false localising sign), not a separate entity requiring its own surgical decompression; management should focus on treating the underlying IIH.', 4),
('d8000000-0000-0000-0000-000000000041', 'E', 'The sixth nerve palsy confirms a diagnosis of myasthenic crisis requiring urgent plasma exchange', false, 'Ruled out because there are no other supporting features of myasthenia gravis (fatigability, ptosis pattern, bulbar symptoms) described, and this presentation is fully explained by raised intracranial pressure from IIH; plasma exchange for myasthenic crisis is not indicated here.', 5),
('d8000000-0000-0000-0000-000000000042', 'A', 'This represents amaurosis fugax and requires urgent same-day TIA pathway assessment as the priority', false, 'Ruled out because amaurosis fugax describes monocular visual loss from retinal/ocular ischaemia, whereas this patient describes a homonymous (binocular, hemifield) pattern typical of cortical (migrainous) visual disturbance, with a long-standing stereotyped history and no vascular risk factors, making migraine with aura far more likely than a vascular TIA-type event.', 1),
('d8000000-0000-0000-0000-000000000042', 'B', 'Migraine with visual aura (cortical spreading depression affecting the occipital cortex), managed with reassurance, migraine trigger/lifestyle advice, and consideration of prophylactic therapy if episodes are frequent or disabling', true, 'Correct. Transient homonymous visual field loss affecting both eyes simultaneously (a cortical, not ocular, pattern), lasting around 20-30 minutes and followed by headache, in a patient with a clear history of similar stereotyped episodes and no vascular risk factors, is classic for migraine with visual aura due to cortical spreading depression in the occipital cortex. Management is reassurance (once red flags for an alternative, more sinister cause have been excluded — such as new onset in an older patient, atypical features, or vascular risk factors), lifestyle/trigger modification advice, and consideration of migraine prophylactic therapy if attacks are frequent or significantly impact quality of life.', 2),
('d8000000-0000-0000-0000-000000000042', 'C', 'Arrange immediate CT angiography to exclude a symptomatic carotid stenosis as the cause', false, 'Ruled out because the described pattern (bilateral homonymous field loss, stereotyped recurrent episodes with headache, longstanding migraine history, no vascular risk factors) is not typical of carotid disease, which would more classically cause monocular symptoms; the clinical picture is well explained by migraine with aura.', 3),
('d8000000-0000-0000-0000-000000000042', 'D', 'Start high-dose oral corticosteroids empirically for presumed optic neuritis', false, 'Ruled out because optic neuritis typically causes monocular (not homonymous bilateral) visual loss with pain on eye movement and is not typically followed by a stereotyped throbbing headache pattern; this presentation is well explained by migraine with visual aura.', 4),
('d8000000-0000-0000-0000-000000000042', 'E', 'Refer for urgent electroencephalography as the priority investigation to exclude occipital lobe seizures', false, 'Ruled out because although occipital seizures are a differential for visual phenomena, the stereotyped history of similar episodes followed by headache over a long period, in a patient with known migraine, makes migraine with aura the most likely diagnosis; EEG is not the immediate priority when the clinical picture is this classic.', 5),
('d8000000-0000-0000-0000-000000000043', 'A', 'Reassure the patient that homonymous hemianopia from stroke always resolves completely within days and requires no specific follow-up', false, 'Ruled out because homonymous hemianopia following established occipital infarction often persists rather than resolving completely, and requires structured follow-up, safety counselling and rehabilitation support rather than blanket reassurance of full recovery.', 1),
('d8000000-0000-0000-0000-000000000043', 'B', 'Arrange emergency intravenous thrombolysis now that the infarct has been identified on CT', false, 'Ruled out because thrombolysis is time-critical and only appropriate within an early window (typically up to 4.5 hours from onset in eligible patients); at around 36 hours post-onset with an established infarct on imaging, thrombolysis is no longer appropriate, and management shifts to secondary prevention and rehabilitation.', 2),
('d8000000-0000-0000-0000-000000000043', 'C', 'Withhold information about the visual field defect from driving licensing authorities, as this is a private medical matter with no legal reporting requirement', false, 'Ruled out because significant homonymous visual field defects have specific driving regulations (varying by jurisdiction) generally requiring disclosure to the relevant licensing authority and cessation of driving until formally assessed as meeting visual field standards; failing to advise on this is a recognised medico-legal and safety concern.', 3),
('d8000000-0000-0000-0000-000000000043', 'D', 'Formally document and quantify the homonymous hemianopia with visual field testing, provide safety advice (e.g. regarding mobility and driving regulations), and refer for visual rehabilitation support alongside standard secondary stroke prevention', true, 'Correct. A homonymous hemianopia following posterior cerebral artery territory (occipital lobe) infarction is a common and often persistent visual field deficit. Once the acute stroke has been appropriately managed, ongoing care includes formal visual field assessment to characterise and monitor the defect, patient safety counselling (including mandatory disclosure to driving licensing authorities, since a significant homonymous field defect is usually incompatible with holding a driving licence until formally assessed), and referral for visual rehabilitation strategies (e.g. compensatory scanning techniques, orientation and mobility support) to help the patient adapt, alongside standard secondary stroke prevention (optimising anticoagulation control, blood pressure, and other vascular risk factors).', 4),
('d8000000-0000-0000-0000-000000000043', 'E', 'Refer for urgent neurosurgical intervention to address the visual field defect directly', false, 'Ruled out because there is no neurosurgical intervention that directly reverses an established cortical visual field defect from infarction; management is supportive, rehabilitative and focused on secondary prevention, not neurosurgery.', 5),
('d8000000-0000-0000-0000-000000000044', 'A', 'Discharge with oral antihypertensive medication and routine GP follow-up in 2 weeks', false, 'Ruled out because this presentation represents a hypertensive emergency with target organ damage (retinal and renal), requiring admission for controlled blood pressure reduction and monitoring, not outpatient management with delayed follow-up.', 1),
('d8000000-0000-0000-0000-000000000044', 'B', 'Rapidly normalise blood pressure to below 120/80 mmHg within the first hour using intravenous agents', false, 'Ruled out because overly rapid blood pressure reduction in malignant hypertension risks watershed ischaemic injury (cerebral, retinal, renal); the correct approach is controlled, gradual reduction over a more extended timeframe under close monitoring, not aggressive normalisation within an hour.', 2),
('d8000000-0000-0000-0000-000000000044', 'C', 'Arrange urgent panretinal photocoagulation for the retinal findings as the priority intervention', false, 'Ruled out because the retinal findings here are due to malignant hypertension, which is managed by controlled systemic blood pressure reduction, not retinal laser treatment, which has no role in hypertensive retinopathy of this type.', 3),
('d8000000-0000-0000-0000-000000000044', 'D', 'Start high-dose corticosteroids for presumed optic neuritis given the bilateral disc swelling', false, 'Ruled out because bilateral disc swelling here is explained by malignant hypertension (hypertensive optic neuropathy/papilloedema secondary to severely elevated blood pressure), not primary inflammatory optic neuritis; corticosteroids are not the appropriate treatment, and the priority is controlled blood pressure reduction.', 4),
('d8000000-0000-0000-0000-000000000044', 'E', 'Admit for urgent, controlled (not overly rapid) reduction of blood pressure with continuous monitoring, given evidence of malignant hypertension with target organ damage (grade 4 hypertensive retinopathy with disc swelling, and acute kidney injury)', true, 'Correct. Bilateral optic disc swelling with flame haemorrhages, cotton wool spots and a macular star, alongside markedly elevated blood pressure and evidence of renal impairment, indicates malignant (accelerated) hypertension with hypertensive emergency and target organ damage (grade 4 retinopathy, acute kidney injury). This requires admission for controlled blood pressure reduction, deliberately avoided as an overly rapid drop, since precipitous lowering risks watershed cerebral or ocular ischaemia; a gradual, monitored reduction over hours to days using appropriate agents is the correct approach, alongside investigation and management of any underlying secondary causes of hypertension and target organ damage.', 5),
('d8000000-0000-0000-0000-000000000045', 'A', 'Manage initially as a presumed microvascular sixth nerve palsy in this vasculopathic patient, with safety-netting and planned early review (e.g. within 6-12 weeks) to confirm resolution, reserving further neuroimaging for atypical features, lack of improvement, or additional neurological signs', true, 'Correct. An isolated, pupil-uninvolved sixth nerve palsy without other neurological or cranial nerve signs, in a patient with vascular risk factors (diabetes, hypertension), and without red flag features (no headache, no other cranial neuropathies, no papilloedema described) is most likely due to microvascular ischaemia of the nerve, and can reasonably be managed with initial safety-netted observation and planned early follow-up to confirm expected spontaneous resolution over weeks. However, this approach requires vigilance: any lack of improvement by the expected timeframe, or development of other neurological signs, headache, or atypical features, should prompt further neuroimaging to exclude other causes (e.g. compressive lesion, raised intracranial pressure).', 1),
('d8000000-0000-0000-0000-000000000045', 'B', 'Arrange emergency MRI brain within the next few hours before any other assessment', false, 'Ruled out because in an isolated, uncomplicated sixth nerve palsy in a vasculopathic patient without red flag features, immediate emergency imaging is not required; a period of safety-netted observation with planned early review is a reasonable initial approach, reserving imaging for atypical or non-resolving cases.', 2),
('d8000000-0000-0000-0000-000000000045', 'C', 'Start empirical high-dose corticosteroids for presumed inflammatory cranial neuropathy', false, 'Ruled out because there is no indication of an inflammatory cause here, and empirical corticosteroids are not appropriate management for a presumed microvascular sixth nerve palsy without other supporting features.', 3),
('d8000000-0000-0000-0000-000000000045', 'D', 'Reassure the patient that no follow-up is needed as this will definitely resolve spontaneously', false, 'Ruled out because although microvascular sixth nerve palsy usually does resolve spontaneously, planned early follow-up is essential to confirm resolution and detect any atypical course requiring further investigation, rather than providing reassurance with no follow-up plan at all.', 4),
('d8000000-0000-0000-0000-000000000045', 'E', 'Refer immediately for strabismus surgery to correct the diplopia', false, 'Ruled out because surgical correction is only considered for persistent, stable diplopia that fails to resolve after an adequate period of observation (often 6-12 months), not as an initial approach to a new, presumed microvascular palsy.', 5),
('d8000000-0000-0000-0000-000000000046', 'A', 'Isolated right third nerve palsy affecting the medial rectus subnucleus', false, 'Ruled out because a third nerve palsy would typically also affect other third-nerve-innervated functions (e.g. ptosis, pupil involvement, other extraocular movements), which are not present here; the described pattern with preserved convergence and nystagmus of the fellow abducting eye specifically localises to the medial longitudinal fasciculus (INO), not a third nerve palsy.', 1),
('d8000000-0000-0000-0000-000000000046', 'B', 'Myasthenia gravis affecting ocular muscles bilaterally', false, 'Ruled out because although myasthenia gravis can cause variable diplopia, the specific and stereotyped pattern described (failure of adduction on conjugate gaze with contralateral abducting nystagmus, preserved convergence) is the classic localising sign of INO from an MLF lesion, not the fatigable, fluctuating pattern typical of myasthenia.', 2),
('d8000000-0000-0000-0000-000000000046', 'C', 'Convergence insufficiency as an isolated benign finding unrelated to her multiple sclerosis', false, 'Ruled out because convergence is explicitly preserved in this case, which is actually a key feature helping to localise the lesion to the MLF (since convergence uses a different pathway) rather than suggesting an isolated convergence disorder.', 3),
('d8000000-0000-0000-0000-000000000046', 'D', 'Internuclear ophthalmoplegia due to a lesion in the right medial longitudinal fasciculus, a recognised presentation of demyelinating disease such as multiple sclerosis', true, 'Correct. The pattern described (impaired adduction of one eye on conjugate gaze to the opposite side, with nystagmus of the abducting fellow eye, but preserved convergence) is the classic presentation of internuclear ophthalmoplegia (INO), localising to a lesion in the medial longitudinal fasciculus on the side of the impaired adduction (here, the right MLF, given failed right eye adduction on left gaze). INO is a recognised and common presentation of demyelinating disease, particularly multiple sclerosis, reflecting a brainstem lesion; bilateral INO is particularly characteristic of MS, while unilateral INO in older patients can also reflect small vessel ischaemic disease.', 4),
('d8000000-0000-0000-0000-000000000046', 'E', 'One-and-a-half syndrome affecting the right pontine gaze centre and both medial longitudinal fasciculi', false, 'Ruled out because one-and-a-half syndrome would produce a combined horizontal gaze palsy on one side plus INO, with very limited horizontal movement of one eye and only abduction preserved in the other; here, only an isolated INO pattern (impaired adduction with contralateral abducting nystagmus, and otherwise normal findings) is described, without a combined gaze palsy component.', 5),
('d8000000-0000-0000-0000-000000000047', 'A', 'This represents a complication directly caused by the cataract surgery performed 5 days earlier, requiring urgent ophthalmic surgical exploration of that eye', false, 'Ruled out because the temporal association and known risk factors (prolonged prone positioning, intraoperative hypotension during spinal surgery) point to perioperative ischaemic optic neuropathy related to the spinal procedure, not a complication of the preceding uneventful cataract surgery; surgical exploration of the cataract wound would not address this ischaemic optic nerve process.', 1),
('d8000000-0000-0000-0000-000000000047', 'B', 'Perioperative (non-arteritic) ischaemic optic neuropathy related to prolonged prone positioning and intraoperative hypotension during spinal surgery, a recognised complication of such procedures', true, $x$Correct. Perioperative ischaemic optic neuropathy is a recognised, though rare, complication of prolonged spine surgery performed in the prone position, particularly associated with intraoperative hypotension, anaemia, prolonged surgical duration, and substantial fluid shifts/facial oedema, which together compromise optic nerve perfusion. It typically presents with painless visual loss noted on waking from anaesthesia, and can be posterior (normal disc initially, more common in this perioperative context) or anterior (disc swelling evolving to pallor, as described here); a prior history of non-arteritic AION indicates an underlying vulnerable ('disc at risk') anatomy that further predisposes to this perioperative ischaemic event.$x$, 2),
('d8000000-0000-0000-0000-000000000047', 'C', 'This is an expected recurrence of arteritic ischaemic optic neuropathy and requires urgent high-dose corticosteroids and temporal artery biopsy', false, 'Ruled out because there is no mention of features suggesting giant cell arteritis (systemic symptoms, raised inflammatory markers), and the clinical context (perioperative, prone positioning, hypotension) strongly supports a perioperative non-arteritic ischaemic optic neuropathy rather than an arteritic process requiring biopsy and steroids.', 3),
('d8000000-0000-0000-0000-000000000047', 'D', 'This represents a retinal detachment secondary to the recent cataract surgery, requiring urgent retinal reattachment surgery', false, 'Ruled out because the clinical description (disc swelling evolving to pallor, painless visual loss on waking) is characteristic of ischaemic optic neuropathy rather than retinal detachment, which would show specific fundoscopic findings (detached retina) rather than optic disc changes; there is no description here of retinal detachment findings.', 4),
('d8000000-0000-0000-0000-000000000047', 'E', 'This is central serous chorioretinopathy related to perioperative corticosteroid use during the spinal surgery', false, 'Ruled out because central serous chorioretinopathy typically presents with more subtle visual distortion/blurring and characteristic subretinal fluid on OCT rather than profound visual loss (counting fingers) with disc swelling evolving to pallor; the perioperative context (prone positioning, hypotension) makes perioperative ischaemic optic neuropathy far more likely.', 5),
('d8000000-0000-0000-0000-000000000048', 'A', 'Reassure the patient that this is a benign, self-limiting condition requiring only routine annual follow-up', false, 'Ruled out because ischaemic CRVO carries a substantial risk of sight- and comfort-threatening neovascular glaucoma within months, requiring close monthly monitoring rather than routine annual review.', 1),
('d8000000-0000-0000-0000-000000000048', 'B', 'Perform prophylactic panretinal photocoagulation immediately in all cases of ischaemic CRVO regardless of neovascularisation status', false, 'Ruled out because prophylactic PRP in all ischaemic CRVO cases (before any neovascularisation develops) is not the universally recommended approach given the risks and side effects of unnecessary laser; the standard approach is close monitoring with prompt PRP triggered by the development of neovascularisation, though practice can vary with individual risk factors and follow-up reliability.', 2),
('d8000000-0000-0000-0000-000000000048', 'C', 'Confirm this as ischaemic central retinal vein occlusion, treat any macular oedema with intravitreal anti-VEGF therapy as needed, and arrange close monthly monitoring for at least 6 months for signs of anterior segment neovascularisation given the high risk of neovascular glaucoma', true, $x$Correct. The combination of marked visual acuity reduction, extensive four-quadrant haemorrhage, a relative afferent pupillary defect, and extensive capillary non-perfusion (>10 disc areas) on angiography confirms ischaemic central retinal vein occlusion, which carries a significant risk (historically cited around 30-60%) of progressing to neovascular glaucoma, particularly within the first 3 months ('90-day glaucoma'). Management includes treating any coexistent macular oedema with anti-VEGF therapy as needed, but critically requires close monthly monitoring (looking specifically for iris/angle neovascularisation via careful anterior segment examination and gonioscopy) for at least the first 6 months, since prompt panretinal photocoagulation at the first sign of neovascularisation can prevent progression to intractable neovascular glaucoma.$x$, 3),
('d8000000-0000-0000-0000-000000000048', 'D', 'Start systemic anticoagulation as the primary treatment to address the venous occlusion', false, 'Ruled out because systemic anticoagulation has not been shown to provide benefit in retinal vein occlusion and is not standard treatment; management focuses on treating macular oedema, monitoring for neovascular complications, and addressing systemic vascular risk factors.', 4),
('d8000000-0000-0000-0000-000000000048', 'E', 'Arrange cataract surgery as the priority intervention to improve visual acuity', false, 'Ruled out because the visual loss here is due to ischaemic CRVO, not cataract; cataract surgery is irrelevant to this presentation and would not address the underlying vascular pathology or associated risks.', 5),
('d8000000-0000-0000-0000-000000000049', 'A', 'Optic nerve sheath meningioma; arrange immediate surgical resection as first-line treatment to preserve remaining vision', false, 'Ruled out because surgical resection of an optic nerve sheath meningioma typically requires removing the optic nerve itself, causing complete visual loss in that eye; this is generally avoided as first-line treatment in patients with useful remaining vision, favouring radiotherapy to preserve the nerve and vision where possible.', 1),
('d8000000-0000-0000-0000-000000000049', 'B', 'Optic glioma; manage with observation alone regardless of visual trajectory, as these tumours are always benign and non-progressive', false, 'Ruled out because the imaging description (tram-track calcification, perioptic enhancing mass) is specific for meningioma rather than glioma (which typically shows fusiform nerve enlargement without the tram-track sign), and observation alone would be inappropriate given progressive visual decline requiring active management consideration (radiotherapy).', 2),
('d8000000-0000-0000-0000-000000000049', 'C', 'Optic neuritis; start high-dose intravenous corticosteroids as first-line treatment', false, 'Ruled out because the clinical course (slowly progressive over 6 weeks, painless, with proptosis and a specific enhancing perioptic mass with calcification on imaging) is not consistent with typical optic neuritis, which is usually more acute and painful; corticosteroids would not address the underlying compressive tumour.', 3),
('d8000000-0000-0000-0000-000000000049', 'D', 'Thyroid eye disease causing compressive optic neuropathy; start high-dose corticosteroids and arrange orbital decompression', false, 'Ruled out because the imaging findings described (discrete enhancing optic nerve sheath mass with tram-track calcification) are specific for optic nerve sheath meningioma, not the diffuse extraocular muscle enlargement typical of thyroid eye disease; there is no mention of thyroid dysfunction or typical thyroid eye disease muscle involvement here.', 4),
('d8000000-0000-0000-0000-000000000049', 'E', 'Optic nerve sheath meningioma; given progressive visual decline, options include fractionated stereotactic radiotherapy (to preserve remaining vision by halting tumour growth), reserving surgical resection for cases where useful vision has already been lost or there is diagnostic uncertainty, since surgery on a nerve sheath meningioma typically sacrifices vision in that eye', true, $x$Correct. The clinical picture (slowly progressive painless visual loss, mild proptosis, and the classic 'tram-track' calcification sign with a homogeneously enhancing perioptic mass on imaging) is characteristic of optic nerve sheath meningioma. Because surgical resection of these tumours typically requires resecting the optic nerve itself (causing blindness in that eye), and the tumours are usually slow-growing, management in patients with useful remaining vision favours fractionated stereotactic radiotherapy, which can halt or reverse further visual decline while preserving the nerve; surgery is generally reserved for cases where vision is already lost, there is diagnostic uncertainty requiring biopsy, or there is significant intracranial extension threatening the chiasm.$x$, 5),
('d8000000-0000-0000-0000-000000000050', 'A', $x$Lateral medullary (Wallenberg) syndrome due to occlusion of the posterior inferior cerebellar artery (or vertebral artery), explaining the crossed sensory loss, ipsilateral Horner's syndrome, ataxia, dysarthria and hiccups$x$, true, $x$Correct. This constellation (ipsilateral facial pain/temperature loss with contralateral body pain/temperature loss — 'crossed' sensory findings — ipsilateral Horner's syndrome, ipsilateral limb/gait ataxia, dysarthria, hiccups, and diplopia/nystagmus) is the classic presentation of lateral medullary syndrome (Wallenberg syndrome), most commonly due to occlusion of the posterior inferior cerebellar artery or the vertebral artery from which it arises. Urgent stroke pathway management (imaging, consideration of thrombolysis/thrombectomy within eligible time windows, and secondary prevention) is required, with recognition of the specific brainstem localisation guiding vascular risk factor management and prognosis discussion.$x$, 1),
('d8000000-0000-0000-0000-000000000050', 'B', 'Locked-in syndrome due to bilateral pontine infarction', false, $x$Ruled out because locked-in syndrome causes quadriplegia and inability to speak with preserved vertical eye movements and consciousness, a very different clinical picture from the crossed sensory loss, Horner's syndrome and ataxia described here, which specifically localise to the lateral medulla.$x$, 2),
('d8000000-0000-0000-0000-000000000050', 'C', 'Weber syndrome due to midbrain infarction affecting the third nerve fascicle and cerebral peduncle', false, $x$Ruled out because Weber syndrome causes an ipsilateral third nerve palsy with contralateral hemiparesis (affecting the corticospinal tract in the peduncle), which is a different pattern from the crossed sensory loss, Horner's syndrome, and cerebellar signs described here, localising instead to the lateral medulla rather than the midbrain.$x$, 3),
('d8000000-0000-0000-0000-000000000050', 'D', 'Guillain-Barre syndrome causing ascending sensory and autonomic dysfunction', false, $x$Ruled out because the described findings (crossed sensory loss, Horner's syndrome, ataxia, dysarthria, hiccups) reflect a discrete brainstem vascular lesion with a classic localising pattern, not the symmetric ascending peripheral neuropathy typical of Guillain-Barre syndrome.$x$, 4),
('d8000000-0000-0000-0000-000000000050', 'E', 'Multiple sclerosis relapse causing a new brainstem demyelinating lesion', false, 'Ruled out because in a 70-year-old man with significant vascular risk factors (hypertension, hyperlipidaemia, heavy smoking history) presenting acutely with this classic brainstem vascular syndrome, an ischaemic stroke (lateral medullary syndrome) is far more likely than a new demyelinating event; multiple sclerosis onset at this age with this specific vascular risk profile would be atypical.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('d8000000-0000-0000-0000-000000000001', 'Sudden monocular visual loss with a pale swollen optic disc, in a patient with systemic features of GCA (headache, jaw claudication, scalp tenderness, weight loss) and markedly raised ESR/CRP, is arteritic AION until proven otherwise and mandates immediate high-dose corticosteroids.', 1),
('d8000000-0000-0000-0000-000000000001', 'Temporal artery biopsy should never delay treatment in suspected GCA with visual symptoms; it remains diagnostically useful for around 2 weeks after starting steroids because granulomatous inflammatory changes persist.', 2),
('d8000000-0000-0000-0000-000000000001', 'Without prompt treatment, the fellow eye is at high risk of sequential ischaemic involvement within days, making this a true ophthalmic and rheumatological emergency.', 3),
('d8000000-0000-0000-0000-000000000002', 'CRAO is increasingly managed as a retinal stroke equivalent; patients presenting within an early time window should be discussed urgently with stroke services for consideration of thrombolysis alongside standard ophthalmic measures.', 1),
('d8000000-0000-0000-0000-000000000002', 'A cherry-red spot with surrounding retinal whitening and profound acute visual loss reflects inner retinal ischaemia from acute arterial occlusion of the central retinal artery.', 2),
('d8000000-0000-0000-0000-000000000002', 'CRAO carries a similar embolic risk profile to cerebral stroke, so urgent identification of a cardioembolic or carotid source is essential even after the acute ophthalmic window has passed.', 3),
('d8000000-0000-0000-0000-000000000003', 'Anti-VEGF therapy is first-line for visually significant macular oedema secondary to branch retinal vein occlusion.', 1),
('d8000000-0000-0000-0000-000000000003', 'BRVO shares vascular risk factors (hypertension, hyperlipidaemia, diabetes) with other systemic vascular disease, so risk factor optimisation is an essential part of management alongside ocular treatment.', 2),
('d8000000-0000-0000-0000-000000000003', 'Absence of a relative afferent pupillary defect and a sectoral (rather than diffuse) pattern of haemorrhage help distinguish BRVO from more extensive central retinal vein occlusion.', 3),
('d8000000-0000-0000-0000-000000000004', 'Vitreous haemorrhage classically presents with sudden painless visual loss, floaters, or a shower of black spots, and is a recognised complication of neovascularisation in proliferative diabetic retinopathy.', 1),
('d8000000-0000-0000-0000-000000000004', 'B-scan ultrasonography is essential when the fundus cannot be visualised, to exclude an underlying retinal detachment, which would change the urgency and nature of surgical management.', 2),
('d8000000-0000-0000-0000-000000000004', 'Conservative management with monitoring is appropriate for vitreous haemorrhage without detachment; vitrectomy is reserved for non-clearing haemorrhage or when detachment is identified.', 3),
('d8000000-0000-0000-0000-000000000005', 'In idiopathic intracranial hypertension, progressive visual field loss despite maximal medical therapy (acetazolamide, weight loss) is an indication for surgical intervention (optic nerve sheath fenestration or CSF diversion) to prevent permanent visual loss.', 1),
('d8000000-0000-0000-0000-000000000005', 'Formal visual field perimetry, not visual acuity alone, is the key measure of optic nerve damage in IIH, since acuity can remain preserved until late in the disease course.', 2),
('d8000000-0000-0000-0000-000000000005', 'Bariatric surgery and sustained weight loss are important longer-term strategies in obese patients with IIH, but do not substitute for urgent surgical protection of vision when field loss is actively progressing.', 3),
('d8000000-0000-0000-0000-000000000006', 'IV methylprednisolone in acute optic neuritis speeds visual recovery but does not change the ultimate visual outcome at 6-12 months.', 1),
('d8000000-0000-0000-0000-000000000006', 'Optic neuritis with MRI evidence of dissemination in space (periventricular/juxtacortical lesions) alongside a prior compatible clinical episode fulfils diagnostic criteria for multiple sclerosis and should trigger neurology referral for disease-modifying therapy.', 2),
('d8000000-0000-0000-0000-000000000006', 'Historical trial data (the Optic Neuritis Treatment Trial) showed an increased relapse rate with oral corticosteroids alone used without preceding IV pulse therapy, informing current practice of avoiding oral-only steroid regimens.', 3),
('d8000000-0000-0000-0000-000000000007', $x$Non-arteritic AION is distinguished from arteritic AION by the absence of systemic GCA features, normal inflammatory markers, a hyperaemic (rather than chalky pale) disc, and typically occurs in patients with vascular risk factors and a crowded 'disc at risk'.$x$, 1),
('d8000000-0000-0000-0000-000000000007', 'Obstructive sleep apnoea is an independent, modifiable risk factor for NAION, and its treatment (e.g. CPAP) is part of comprehensive management even though it does not reverse existing visual loss.', 2),
('d8000000-0000-0000-0000-000000000007', 'There is no proven treatment (steroid or otherwise) that reliably reverses established visual loss in NAION; management is supportive and focused on secondary prevention, including fellow-eye risk reduction.', 3),
('d8000000-0000-0000-0000-000000000008', $x$Hydroxychloroquine retinopathy classically produces a bull's-eye maculopathy with paracentral scotomas and, on OCT, loss of the parafoveal ellipsoid zone described as the 'flying saucer sign'.$x$, 1),
('d8000000-0000-0000-0000-000000000008', 'Cumulative dose above 5 mg/kg/day (actual body weight) and treatment duration beyond 5 years are the major risk factors for hydroxychloroquine retinopathy, underlying the rationale for annual screening after 5 years of use.', 2),
('d8000000-0000-0000-0000-000000000008', 'Once retinal toxicity is identified, hydroxychloroquine should be discontinued, as toxicity can continue to progress even after stopping the drug, particularly with ongoing exposure above recommended dosing thresholds.', 3),
('d8000000-0000-0000-0000-000000000009', 'Radial perineural infiltrates and ring-shaped stromal infiltrates in a contact lens wearer, especially with poor response to antibacterial therapy, should prompt specific investigation and treatment for Acanthamoeba keratitis.', 1),
('d8000000-0000-0000-0000-000000000009', 'Acanthamoeba keratitis is classically associated with contact lens wear (particularly exposure to tap water, swimming, or poor lens hygiene) and can mimic herpetic or bacterial keratitis, leading to diagnostic delay.', 2),
('d8000000-0000-0000-0000-000000000009', 'Topical biguanides (e.g. polyhexamethylene biguanide or chlorhexidine), often combined with a diamidine, are the mainstay of medical treatment for Acanthamoeba keratitis, and early initiation improves visual outcomes.', 3),
('d8000000-0000-0000-0000-000000000010', 'In treat-and-extend regimens for neovascular AMD, new fluid or symptomatic reactivation ahead of a scheduled visit indicates the interval has been extended too far and should prompt bringing treatment forward and shortening the interval.', 1),
('d8000000-0000-0000-0000-000000000010', 'Persistent or recurrent breakthrough disease activity despite interval adjustment is a recognised indication to consider switching to an alternative anti-VEGF agent.', 2),
('d8000000-0000-0000-0000-000000000010', 'Regular self-monitoring with an Amsler grid helps patients detect early reactivation of neovascular AMD between scheduled visits, prompting earlier review.', 3),
('d8000000-0000-0000-0000-000000000011', 'Trapdoor orbital floor fractures with true muscle entrapment, particularly in children and young adults, are surgical emergencies requiring repair within 24-48 hours to prevent permanent ischaemic muscle fibrosis.', 1),
('d8000000-0000-0000-0000-000000000011', 'The oculocardiac reflex (bradycardia, nausea, vomiting) triggered by extraocular muscle traction is a red flag for entrapment and mandates urgent assessment.', 2),
('d8000000-0000-0000-0000-000000000011', $x$A 'white-eyed blowout fracture' describes a deceptively quiet-looking globe/orbit despite significant underlying entrapment, and should not be mistaken for a minor injury on external appearance alone.$x$, 3),
('d8000000-0000-0000-0000-000000000012', $x$Neovascular glaucoma classically develops around 90 days after ischaemic central retinal vein occlusion ('90-day glaucoma'), driven by VEGF release from ischaemic retina causing new vessels at the iris and angle.$x$, 1),
('d8000000-0000-0000-0000-000000000012', 'Panretinal photocoagulation is the definitive treatment to reduce the ischaemic drive behind neovascularisation, often supplemented by intravitreal anti-VEGF for faster regression while awaiting laser effect.', 2),
('d8000000-0000-0000-0000-000000000012', 'Distinguishing ischaemic from non-ischaemic CRVO at presentation (extent of haemorrhage, degree of visual loss, relative afferent pupillary defect, capillary non-perfusion on angiography) helps predict the risk of later neovascular complications and guides surveillance intensity.', 3),
('d8000000-0000-0000-0000-000000000013', 'Rapid correction of longstanding severe hyperglycaemia can cause transient early worsening of diabetic retinopathy, a recognised phenomenon that is usually self-limiting but warrants closer monitoring.', 1),
('d8000000-0000-0000-0000-000000000013', 'The correct response to early worsening is not to withhold appropriate glycaemic control, but to continue it while increasing surveillance frequency, reserving specific retinal treatment for those who progress to sight-threatening disease.', 2),
('d8000000-0000-0000-0000-000000000013', 'This phenomenon is particularly relevant in patients starting insulin pump therapy, undergoing rapid glycaemic optimisation in pregnancy, or receiving intensive inpatient glucose correction.', 3),
('d8000000-0000-0000-0000-000000000014', 'Intravitreal anti-VEGF therapy is first-line for centre-involving diabetic macular oedema causing visual impairment, requiring an initial loading phase of frequent injections to achieve disease control.', 1),
('d8000000-0000-0000-0000-000000000014', 'Focal/grid laser remains useful for non-centre-involving oedema or as an adjunct, but is no longer first-line when the centre of the macula is involved with reduced vision.', 2),
('d8000000-0000-0000-0000-000000000014', 'Intravitreal corticosteroids are typically reserved for second-line use, particularly in pseudophakic patients or anti-VEGF non-responders, due to their cataract and intraocular pressure side-effect profile.', 3),
('d8000000-0000-0000-0000-000000000015', 'Inadequate anatomical/functional response after a full loading course of one anti-VEGF agent should prompt switching to an alternative anti-VEGF agent or considering intravitreal corticosteroid therapy, rather than continuing unchanged treatment indefinitely.', 1),
('d8000000-0000-0000-0000-000000000015', 'Intravitreal corticosteroids act via a different (anti-inflammatory) mechanism than anti-VEGF agents and can be effective in partial or non-responders, though cataract progression and intraocular pressure rise must be monitored, particularly in phakic patients.', 2),
('d8000000-0000-0000-0000-000000000015', 'Individual patient response to different anti-VEGF agents can vary meaningfully, providing the rationale for a trial of an alternative agent before escalating to other modalities.', 3),
('d8000000-0000-0000-0000-000000000016', $x$Severe non-proliferative diabetic retinopathy meeting the '4-2-1 rule' (haemorrhages in all 4 quadrants, venous beading in ≥2 quadrants, or IRMA in ≥1 quadrant) carries a high risk of progression to proliferative disease within a year and requires closer surveillance than routine screening intervals.$x$, 1),
('d8000000-0000-0000-0000-000000000016', 'Early panretinal photocoagulation before frank proliferative changes may be considered in selected high-risk severe NPDR patients, particularly where reliable follow-up cannot be guaranteed.', 2),
('d8000000-0000-0000-0000-000000000016', 'Visual acuity is a poor marker of diabetic retinopathy severity/risk, since severe structural disease can exist with entirely preserved central vision until late complications develop.', 3),
('d8000000-0000-0000-0000-000000000017', 'Panretinal photocoagulation can precipitate or worsen macular oedema, likely via a transient post-laser inflammatory and VEGF-mediated response, and this should be actively monitored for after treatment.', 1),
('d8000000-0000-0000-0000-000000000017', 'New or worsening centre-involving macular oedema after PRP is appropriately treated with intravitreal anti-VEGF therapy, which can be given alongside ongoing management of the proliferative disease.', 2),
('d8000000-0000-0000-0000-000000000017', 'Combining anti-VEGF therapy with panretinal photocoagulation is a recognised strategy in patients with both proliferative disease and macular oedema, addressing both pathological processes concurrently.', 3),
('d8000000-0000-0000-0000-000000000018', 'Persistent or recurrent neovascular glaucoma despite panretinal photocoagulation (including intraoperative endolaser) should prompt reassessment for under-treated or inaccessible peripheral ischaemic retina, which may benefit from supplementary laser.', 1),
('d8000000-0000-0000-0000-000000000018', 'Intravitreal anti-VEGF therapy provides more rapid regression of iris/angle neovascularisation than laser alone and is a valuable adjunct in neovascular glaucoma while the ischaemic drive is being addressed.', 2),
('d8000000-0000-0000-0000-000000000018', 'Peripheral retina, particularly anteriorly, can be technically difficult to treat completely with endolaser at the time of vitrectomy, making residual ischaemia a recognised cause of postoperative neovascular complications.', 3),
('d8000000-0000-0000-0000-000000000019', 'Pregnancy is an independent risk factor for progression of diabetic retinopathy, and increased surveillance frequency (typically each trimester or more often if disease is advancing) is recommended throughout pregnancy.', 1),
('d8000000-0000-0000-0000-000000000019', 'Rapid glycaemic optimisation, while beneficial overall in pregnancy, can be associated with short-term worsening of retinopathy, reinforcing the need for closer monitoring rather than a change in glycaemic strategy.', 2),
('d8000000-0000-0000-0000-000000000019', 'Sight-threatening retinopathy identified during pregnancy should still be treated (e.g. with laser or, where necessary, intravitreal therapy after careful risk-benefit discussion) rather than deferred until after delivery.', 3),
('d8000000-0000-0000-0000-000000000020', 'Tractional retinal detachment threatening the fovea in proliferative diabetic retinopathy should prompt timely vitrectomy before foveal involvement occurs, since visual outcomes are significantly better with earlier surgical intervention.', 1),
('d8000000-0000-0000-0000-000000000020', 'Vitrectomy for tractional detachment involves relief of vitreoretinal traction (membrane peeling, segmentation/delamination) and typically allows completion of panretinal photocoagulation.', 2),
('d8000000-0000-0000-0000-000000000020', 'Anti-VEGF therapy may be used adjunctively before vitrectomy to reduce fibrovascular membrane vascularity and intraoperative bleeding risk, but does not replace the need for mechanical relief of traction.', 3),
('d8000000-0000-0000-0000-000000000021', 'Panretinal photocoagulation is a recognised cause of peripheral visual field constriction and impaired night vision due to destruction of peripheral rod photoreceptors, an accepted trade-off for preventing more severe complications of proliferative retinopathy.', 1),
('d8000000-0000-0000-0000-000000000021', 'Central visual acuity is typically preserved after PRP because treatment spares the macula, meaning good acuity does not exclude significant peripheral visual dysfunction.', 2),
('d8000000-0000-0000-0000-000000000021', 'Patients undergoing extensive PRP should be counselled about potential effects on night driving and peripheral vision, which may have practical and occupational (e.g. driving licence) implications.', 3),
('d8000000-0000-0000-0000-000000000022', 'Intravitreal anti-VEGF agents carry a small but recognised risk of arterial thromboembolic events due to systemic absorption, relevant to individualised risk-benefit discussions in patients with significant cardiovascular disease.', 1),
('d8000000-0000-0000-0000-000000000022', 'Recent myocardial infarction is not an absolute contraindication to anti-VEGF therapy, but warrants careful discussion, potentially with cardiology input, rather than automatic avoidance or automatic proceeding without discussion.', 2),
('d8000000-0000-0000-0000-000000000022', 'This systemic safety consideration is a distinguishing feature of anti-VEGF pharmacology relevant to higher-level therapeutics decision-making, beyond simply knowing the ocular indication and mechanism.', 3),
('d8000000-0000-0000-0000-000000000023', 'Early worsening of diabetic retinopathy can occur with rapid glycaemic improvement from any effective glucose-lowering strategy, not solely with insulin therapy, and is usually transient and self-limiting.', 1),
('d8000000-0000-0000-0000-000000000023', 'The appropriate response to early worsening is closer ophthalmological surveillance rather than reversing beneficial diabetes treatment, since long-term glycaemic control remains protective against retinopathy progression.', 2),
('d8000000-0000-0000-0000-000000000023', 'Distinguishing transient early worsening from true disease progression requiring treatment relies on the trajectory of change and category of retinopathy (non-proliferative vs proliferative), not simply the presence of any interval change.', 3),
('d8000000-0000-0000-0000-000000000024', 'A treat-and-extend approach allows cautious lengthening of injection intervals in patients with a sustained good response to anti-VEGF therapy, balancing reduced treatment burden against the risk of recurrence.', 1),
('d8000000-0000-0000-0000-000000000024', 'Diabetic macular oedema is a chronic condition requiring ongoing monitoring even after a period of good control, since abrupt discontinuation without a monitoring plan risks unrecognised recurrence.', 2),
('d8000000-0000-0000-0000-000000000024', $x$Shared decision-making that acknowledges a patient's practical burden of treatment (e.g. caring responsibilities, travel) while maintaining a safe monitoring structure is an important part of individualised long-term DMO management.$x$, 3),
('d8000000-0000-0000-0000-000000000025', 'Anti-VEGF monotherapy is an evidence-based alternative to panretinal photocoagulation for proliferative diabetic retinopathy but depends on sustained, reliable long-term follow-up, unlike the more durable, one-off effect of laser.', 1),
('d8000000-0000-0000-0000-000000000025', 'Patients at higher risk of loss to follow-up should have this risk explicitly factored into the choice between anti-VEGF monotherapy and panretinal photocoagulation for proliferative disease, favouring the more durable option when adherence is uncertain.', 2),
('d8000000-0000-0000-0000-000000000025', 'Occupational visual field requirements (e.g. driving) are a legitimate part of the shared decision-making discussion when choosing between panretinal photocoagulation and anti-VEGF therapy for proliferative diabetic retinopathy.', 3),
('d8000000-0000-0000-0000-000000000026', 'Treatment thresholds for diabetic macular oedema are based on whether the centre of the macula is involved and whether visual acuity is affected, not simply the presence of any oedema on OCT.', 1),
('d8000000-0000-0000-0000-000000000026', 'Non-centre-involving macular oedema with preserved visual acuity is appropriately managed with closer-interval monitoring rather than immediate anti-VEGF or laser treatment, reserving active treatment for progression.', 2),
('d8000000-0000-0000-0000-000000000026', 'Unnecessary early treatment of diabetic macular oedema carries its own risks and burdens, reinforcing the rationale for a monitoring-based approach until a recognised treatment threshold is reached.', 3),
('d8000000-0000-0000-0000-000000000027', 'Frequent recurrent HLA-B27-associated anterior uveitis can be managed with long-term low-dose topical prophylaxis or, in refractory/frequent cases, systemic immunosuppression or biologic therapy (e.g. adalimumab) via rheumatology.', 1),
('d8000000-0000-0000-0000-000000000027', 'Cumulative complications of recurrent anterior uveitis (posterior synechiae, cataract, secondary glaucoma) provide the rationale for considering preventive strategies rather than only treating each acute episode.', 2),
('d8000000-0000-0000-0000-000000000027', 'TNF-alpha inhibitors, particularly adalimumab, have a recognised evidence base for reducing recurrence in refractory non-infectious anterior uveitis, including HLA-B27-associated disease.', 3),
('d8000000-0000-0000-0000-000000000028', 'Topical corticosteroids have minimal posterior segment penetration and are inadequate for treating vitritis, periphlebitis, or macular oedema in panuveitis; systemic or local periocular/intravitreal therapy is required for posterior involvement.', 1),
('d8000000-0000-0000-0000-000000000028', $x$Sarcoid uveitis classically produces mutton-fat keratic precipitates, vitreous snowballs/snowbanking, and periphlebitis with 'candle-wax drippings', reflecting granulomatous inflammation.$x$, 2),
('d8000000-0000-0000-0000-000000000028', 'Systemic disease activity (e.g. hilar lymphadenopathy on imaging) does not necessarily correlate with ocular disease activity, so ocular inflammation must be assessed and treated on its own merits.', 3),
('d8000000-0000-0000-0000-000000000029', $x$Recurrent sight-threatening flares of Behçet's uveitis despite conventional immunosuppression (azathioprine, corticosteroids) are an indication to escalate to biologic therapy, with anti-TNF agents (infliximab, adalimumab) having the strongest evidence base.$x$, 1),
('d8000000-0000-0000-0000-000000000029', $x$Behçet's disease retinal vasculitis carries a high risk of cumulative visual loss from recurrent occlusive vasculitis, underscoring the importance of early and adequate immunosuppressive escalation in refractory disease.$x$, 2),
('d8000000-0000-0000-0000-000000000029', $x$Interferon-alpha is an alternative escalation option to anti-TNF therapy in refractory Behçet's uveitis, reflecting the range of modern biologic/immunomodulatory strategies available for this condition.$x$, 3),
('d8000000-0000-0000-0000-000000000030', 'JIA-associated chronic anterior uveitis is characteristically asymptomatic, in contrast to the typically painful, photophobic presentation of HLA-B27-associated acute anterior uveitis, making regular screening essential regardless of symptoms.', 1),
('d8000000-0000-0000-0000-000000000030', 'Cumulative complications of chronic paediatric uveitis (band keratopathy, cataract, glaucoma, synechiae) can develop silently without adequate screening and treatment of subclinical inflammation.', 2),
('d8000000-0000-0000-0000-000000000030', 'Detection of breakthrough inflammation despite methotrexate should prompt consideration of treatment escalation (e.g. biologic therapy) rather than simply discontinuing existing steroid-sparing treatment.', 3),
('d8000000-0000-0000-0000-000000000031', 'Acute postoperative endophthalmitis presenting with hypopyon, vitritis, pain and rapid visual decline in the days after intraocular surgery is a sight-threatening emergency requiring immediate vitreous/aqueous sampling and empirical intravitreal antibiotics.', 1),
('d8000000-0000-0000-0000-000000000031', 'Empirical intravitreal antibiotic choice (typically vancomycin plus ceftazidime) should not be delayed pending culture results, given the rapid, potentially devastating course of endophthalmitis.', 2),
('d8000000-0000-0000-0000-000000000031', 'Presenting visual acuity (e.g. perception of light only) guides the decision for immediate vitrectomy versus tap-and-inject as initial management, based on evidence from the Endophthalmitis Vitrectomy Study.', 3),
('d8000000-0000-0000-0000-000000000032', 'Electroretinogram parameters are an important objective marker of disease activity in birdshot chorioretinopathy, capable of detecting progressive retinal dysfunction that may not be obvious on fundoscopy alone.', 1),
('d8000000-0000-0000-0000-000000000032', 'Breakthrough disease activity despite adequate conventional immunosuppression (e.g. mycophenolate) in birdshot chorioretinopathy is an indication to escalate treatment, increasingly involving biologic agents in refractory cases.', 2),
('d8000000-0000-0000-0000-000000000032', 'Birdshot chorioretinopathy is strongly associated with HLA-A29 and is managed as a chronic autoimmune chorioretinopathy requiring long-term immunosuppression tailored to ongoing disease activity monitoring.', 3),
('d8000000-0000-0000-0000-000000000033', 'Recurrent acute unilateral anterior uveitis with features of inflammatory back pain (age under 40, insidious onset, morning stiffness improved by exercise, duration over 3 months) should prompt rheumatological assessment for axial spondyloarthritis.', 1),
('d8000000-0000-0000-0000-000000000033', 'Treatment of the acute uveitis itself (topical corticosteroids and cycloplegics) should not be delayed pending systemic investigations such as HLA-B27 testing or rheumatology review.', 2),
('d8000000-0000-0000-0000-000000000033', 'The recognised association between HLA-B27-related acute anterior uveitis and spondyloarthropathies (ankylosing spondylitis, reactive arthritis, psoriatic arthritis, inflammatory bowel disease-associated arthritis) underlies the rationale for a broader systemic history and targeted referral.', 3),
('d8000000-0000-0000-0000-000000000034', $x$Steroid-induced ocular hypertension ('steroid response') is a recognised complication of topical corticosteroid treatment for uveitis, more common with potent agents such as dexamethasone, and requires active management rather than being disregarded.$x$, 1),
('d8000000-0000-0000-0000-000000000034', 'Management balances two competing risks: glaucomatous optic nerve damage from elevated pressure versus uveitis recurrence from steroid withdrawal, favouring a gradual, monitored taper alongside pressure-lowering treatment rather than abrupt cessation.', 2),
('d8000000-0000-0000-0000-000000000034', 'Switching to a lower-potency or lower-penetration corticosteroid (e.g. fluorometholone or loteprednol) is a recognised strategy to reduce the risk of steroid-induced pressure elevation while still controlling inflammation.', 3),
('d8000000-0000-0000-0000-000000000035', $x$CMV retinitis classically presents in advanced HIV/AIDS (typically CD4 <50 cells/microlitre) with granular, haemorrhagic retinal necrosis following the vascular arcades ('pizza pie' fundus), often with relatively little vitreous inflammation.$x$, 1),
('d8000000-0000-0000-0000-000000000035', 'Treatment requires antiviral therapy (systemic valganciclovir, with intravenous or intravitreal options for severe disease) alongside urgent optimisation of antiretroviral therapy for immune reconstitution.', 2),
('d8000000-0000-0000-0000-000000000035', 'Immune reconstitution inflammatory syndrome-related uveitis is a recognised risk when antiretroviral therapy restores immune function in the presence of ongoing or recently treated CMV retinitis, requiring careful monitoring during this transition.', 3),
('d8000000-0000-0000-0000-000000000036', 'Necrotising scleritis (non-blanching deep vascular injection, severe pain, scleral thinning with visible uvea) is distinguished from episcleritis and non-necrotising scleritis by its severity and association with systemic vasculitic disease, and carries a real risk of scleral perforation.', 1),
('d8000000-0000-0000-0000-000000000036', 'Necrotising scleritis in rheumatoid arthritis is a marker of severe systemic vasculitic disease activity and is associated with increased mortality if untreated, mandating urgent systemic immunosuppression rather than topical treatment alone.', 2),
('d8000000-0000-0000-0000-000000000036', 'Close liaison with rheumatology for systemic immunosuppressive escalation (rather than simply stopping current therapy) is central to managing scleritis associated with underlying autoimmune disease.', 3),
('d8000000-0000-0000-0000-000000000037', $x$Sympathetic ophthalmia is bilateral granulomatous panuveitis developing after penetrating trauma or intraocular surgery to one eye, with inflammation appearing in the previously uninjured 'sympathising' eye, and can be accompanied by vitiligo-like skin/hair changes similar to Vogt-Koyanagi-Harada syndrome.$x$, 1),
('d8000000-0000-0000-0000-000000000037', 'Enucleation of a severely injured, non-visually-useful eye within around 2 weeks of injury is a recognised preventive strategy against sympathetic ophthalmia, but once the condition has developed, enucleation of the exciting eye does not reliably alter the disease course in the fellow eye.', 2),
('d8000000-0000-0000-0000-000000000037', 'Management once sympathetic ophthalmia is established is aggressive systemic immunosuppression (corticosteroids, escalating to steroid-sparing agents) aimed at protecting vision in the sympathising eye.', 3),
('d8000000-0000-0000-0000-000000000038', $x$Inadequate treatment duration or overly rapid corticosteroid tapering in Vogt-Koyanagi-Harada disease is strongly associated with progression to a chronic recurrent phase with a 'sunset glow fundus' and worse long-term visual outcomes.$x$, 1),
('d8000000-0000-0000-0000-000000000038', 'Current management of VKH disease favours high-dose initial corticosteroids maintained over a prolonged period with a slow taper (often at least 6 months), sometimes with early steroid-sparing immunosuppression, to prevent chronic recurrent disease.', 2),
('d8000000-0000-0000-0000-000000000038', 'VKH disease is a systemic autoimmune syndrome, with extra-ocular features (auditory symptoms such as tinnitus, integumentary changes such as poliosis, alopecia and vitiligo, and CSF pleocytosis) supporting the diagnosis alongside the characteristic ocular findings.', 3),
('d8000000-0000-0000-0000-000000000039', 'A third nerve palsy with pupillary involvement should be treated as a compressive lesion (classically a posterior communicating artery aneurysm) until proven otherwise, requiring urgent vascular imaging.', 1),
('d8000000-0000-0000-0000-000000000039', 'Pupil-sparing third nerve palsy in a vasculopathic patient is more typically attributed to microvascular ischaemia, though careful monitoring for evolving pupillary involvement over the following days remains important.', 2),
('d8000000-0000-0000-0000-000000000039', $x$The 'down and out' eye position with ptosis reflects unopposed action of the lateral rectus (abducens) and superior oblique (trochlear) muscles when the third-nerve-innervated muscles are paralysed.$x$, 3),
('d8000000-0000-0000-0000-000000000040', 'Amaurosis fugax (transient monocular visual loss) is a retinal TIA-equivalent event carrying a significant short-term risk of stroke and requires urgent same-day specialist assessment, not routine or delayed follow-up.', 1),
('d8000000-0000-0000-0000-000000000040', 'Carotid imaging is a key investigation in amaurosis fugax to identify significant carotid stenosis that may benefit from urgent revascularisation (endarterectomy or stenting).', 2),
('d8000000-0000-0000-0000-000000000040', 'Underlying atrial fibrillation with contraindications to standard anticoagulation requires specialist input to weigh embolic stroke risk against bleeding risk, potentially including alternative stroke-prevention strategies.', 3),
('d8000000-0000-0000-0000-000000000041', $x$A sixth nerve palsy is a well-recognised 'false localising sign' of raised intracranial pressure of any cause, related to the nerve's long intracranial course making it vulnerable to stretch, rather than indicating a distinct structural lesion.$x$, 1),
('d8000000-0000-0000-0000-000000000041', 'In idiopathic intracranial hypertension, cranial nerve palsies such as a sixth nerve palsy are expected to improve as intracranial pressure is controlled with appropriate treatment (acetazolamide, weight management, and escalation as needed).', 2),
('d8000000-0000-0000-0000-000000000041', 'A false localising sign should not be over-investigated as if it were a separate localising neurological finding once the underlying cause of raised intracranial pressure has been adequately established.', 3),
('d8000000-0000-0000-0000-000000000042', 'Homonymous (binocular, same-sided) visual field disturbances reflect retrochiasmal/cortical pathology, distinguishing them from monocular visual loss (which localises to one eye/optic nerve, such as amaurosis fugax).', 1),
('d8000000-0000-0000-0000-000000000042', 'Migraine with visual aura classically produces a gradually evolving, stereotyped visual disturbance (e.g. scintillating scotoma, expanding fortification spectra, or hemifield loss) lasting 20-60 minutes, followed by headache.', 2),
('d8000000-0000-0000-0000-000000000042', 'A longstanding history of stereotyped episodes in a patient without vascular risk factors reduces the likelihood of an alternative vascular or structural cause, though new atypical features at any point should prompt re-evaluation.', 3),
('d8000000-0000-0000-0000-000000000043', 'Homonymous hemianopia from posterior cerebral artery/occipital lobe infarction often persists and requires formal visual field assessment, safety counselling, and referral for visual rehabilitation rather than an assumption of spontaneous full recovery.', 1),
('d8000000-0000-0000-0000-000000000043', 'Patients with significant homonymous visual field defects generally must not drive until formally assessed against visual field standards, and clinicians have a responsibility to advise patients of relevant driving regulations and reporting requirements.', 2),
('d8000000-0000-0000-0000-000000000043', 'Thrombolysis is time-critical and not appropriate once a stroke is established beyond the eligible treatment window; later-presenting or already-infarcted strokes are managed with secondary prevention and rehabilitation.', 3),
('d8000000-0000-0000-0000-000000000044', 'Malignant (accelerated) hypertension with bilateral disc swelling, flame haemorrhages, cotton wool spots and macular star represents grade 4 hypertensive retinopathy and is a hypertensive emergency requiring admission.', 1),
('d8000000-0000-0000-0000-000000000044', 'Blood pressure reduction in hypertensive emergencies should be controlled and gradual rather than rapidly normalised, since precipitous reduction risks watershed ischaemic complications in the brain, retina, and kidneys.', 2),
('d8000000-0000-0000-0000-000000000044', 'Evidence of target organ damage (retinopathy, acute kidney injury) alongside markedly elevated blood pressure defines a hypertensive emergency requiring admission, distinct from asymptomatic severe hypertension which can often be managed with more gradual outpatient escalation.', 3),
('d8000000-0000-0000-0000-000000000045', 'An isolated, pupil-uninvolved sixth nerve palsy without other neurological signs in a vasculopathic patient is commonly due to microvascular ischaemia and can be managed initially with safety-netted observation and planned early review.', 1),
('d8000000-0000-0000-0000-000000000045', 'Lack of expected improvement within the anticipated timeframe, or the development of additional neurological signs, headache, or other atypical features, should prompt escalation to neuroimaging even after an initially reassuring presentation.', 2),
('d8000000-0000-0000-0000-000000000045', 'Definitive surgical correction of persistent diplopia (e.g. prism therapy or strabismus surgery) is reserved for cases that remain stable and unresolved after an adequate period of observation, not offered as an immediate first-line response.', 3),
('d8000000-0000-0000-0000-000000000046', 'Internuclear ophthalmoplegia is characterised by impaired adduction of one eye on conjugate horizontal gaze with nystagmus of the contralateral abducting eye, but preserved convergence, localising to the medial longitudinal fasciculus on the side of impaired adduction.', 1),
('d8000000-0000-0000-0000-000000000046', $x$Bilateral INO is particularly characteristic of multiple sclerosis, reflecting the demyelinating disease's predilection for periventricular brainstem white matter tracts.$x$, 2),
('d8000000-0000-0000-0000-000000000046', 'Distinguishing INO from other causes of diplopia (cranial nerve palsies, myasthenia gravis, one-and-a-half syndrome) relies on recognising this specific dissociated eye movement pattern and the preservation of convergence.', 3),
('d8000000-0000-0000-0000-000000000047', 'Perioperative ischaemic optic neuropathy is a recognised, rare but devastating complication of prolonged prone-position spine surgery, associated with intraoperative hypotension, anaemia, prolonged duration, and significant fluid administration/facial oedema.', 1),
('d8000000-0000-0000-0000-000000000047', $x$A prior history of non-arteritic AION indicates an anatomically vulnerable ('disc at risk') optic nerve that may further predispose a patient to perioperative ischaemic events under conditions of compromised perfusion.$x$, 2),
('d8000000-0000-0000-0000-000000000047', 'Perioperative ischaemic optic neuropathy typically presents with painless visual loss noted on waking from anaesthesia and can be posterior (normal-appearing disc acutely) or anterior (disc swelling evolving to pallor) in type.', 3),
('d8000000-0000-0000-0000-000000000048', 'Ischaemic central retinal vein occlusion (extensive haemorrhage, marked acuity reduction, RAPD, and significant capillary non-perfusion on angiography) carries a high risk of progression to neovascular glaucoma, particularly within the first 3 months.', 1),
('d8000000-0000-0000-0000-000000000048', 'Close monthly monitoring for anterior segment neovascularisation, including gonioscopy, for at least 6 months is essential after ischaemic CRVO, since prompt panretinal photocoagulation at the first sign of neovascularisation can prevent progression to neovascular glaucoma.', 2),
('d8000000-0000-0000-0000-000000000048', 'Distinguishing ischaemic from non-ischaemic CRVO at presentation (degree of visual loss, RAPD, extent of haemorrhage, and fluorescein angiography non-perfusion) is critical for risk-stratifying the intensity of follow-up required.', 3),
('d8000000-0000-0000-0000-000000000049', $x$Optic nerve sheath meningioma classically shows a 'tram-track' sign of calcification alongside a homogeneously enhancing perioptic mass on imaging, distinguishing it from optic nerve glioma (fusiform nerve enlargement, more common in children, often associated with neurofibromatosis type 1).$x$, 1),
('d8000000-0000-0000-0000-000000000049', 'Surgical resection of optic nerve sheath meningioma typically sacrifices vision in the affected eye because the tumour is intimately associated with the nerve itself, so radiotherapy is favoured in patients with useful remaining vision to halt progression while preserving the nerve.', 2),
('d8000000-0000-0000-0000-000000000049', 'Fractionated stereotactic radiotherapy has become the preferred first-line treatment for optic nerve sheath meningioma with progressive visual decline, reserving surgery for eyes with no useful vision remaining or diagnostic uncertainty.', 3),
('d8000000-0000-0000-0000-000000000050', $x$Lateral medullary (Wallenberg) syndrome produces a characteristic 'crossed' sensory pattern (ipsilateral facial and contralateral body pain/temperature loss) reflecting involvement of the ipsilateral trigeminal spinal tract/nucleus and the contralateral spinothalamic tract.$x$, 1),
('d8000000-0000-0000-0000-000000000050', $x$Associated ipsilateral Horner's syndrome (descending sympathetic fibres), ataxia (inferior cerebellar peduncle/cerebellum), dysarthria, and hiccups (thought to relate to medullary respiratory/vomiting centre involvement) are classic accompanying features localising to the lateral medulla.$x$, 2),
('d8000000-0000-0000-0000-000000000050', 'This syndrome most commonly results from occlusion of the posterior inferior cerebellar artery or the vertebral artery, and recognising the pattern allows rapid localisation and appropriate urgent stroke pathway management.', 3);
